# ==============================================================================
# CASE-INSENSITIVE STATUS HELPERS (for data integrity across pipeline)
# ==============================================================================
def status_eq(item: Dict, *statuses: str) -> bool:
    """
    Case-insensitive status check for an item.
    Handles both exact matches and space/underscore variations.
    Example: status_eq(claim, 'approved', 'paid') checks if status is 'Approved', 'approved', 'APPROVED', etc.
    """
    item_status = (item.get('status') or '').lower().replace(' ', '_')
    return item_status in [s.lower().replace(' ', '_') for s in statuses]

def status_in(item: Dict, statuses: list) -> bool:
    """
    Case-insensitive check if item's status is in a list of statuses.
    Example: status_in(claim, ['pending', 'under_review'])
    """
    item_status = (item.get('status') or '').lower().replace(' ', '_')
    return item_status in [s.lower().replace(' ', '_') for s in statuses]

def get_status_lower(item: Dict) -> str:
    """Get item's status in lowercase with spaces converted to underscores."""
    return (item.get('status') or '').lower().replace(' ', '_')


# ==============================================================================
# DATA INTEGRITY: Safe numeric conversion for consistent calculations
# ==============================================================================
def safe_float(val, default: float = 0.0) -> float:
    """
    Safely convert value to float, handling None, empty strings, and invalid types.
    
    This function ensures data integrity across all dashboard calculations by
    preventing TypeErrors and ValueErrors when summing numeric fields that may
    be stored as strings or contain null values.
    
    Args:
        val: The value to convert (can be int, float, str, None)
        default: Default value if conversion fails
    
    Returns:
        float: The converted value or default
    
    Examples:
        safe_float(100) -> 100.0
        safe_float("100.50") -> 100.5
        safe_float(None) -> 0.0
        safe_float("invalid") -> 0.0
    """
    if val is None:
        return default
    try:
        return float(val)
    except (TypeError, ValueError):
        return default


def safe_int(val, default: int = 0) -> int:
    """
    Safely convert value to int, handling None, empty strings, and invalid types.
    
    Args:
        val: The value to convert
        default: Default value if conversion fails
    
    Returns:
        int: The converted value or default
    """
    if val is None:
        return default
    try:
        return int(float(val))  # Handle "100.0" string -> 100
    except (TypeError, ValueError):
        return default


# Premium-related transaction categories used for revenue reconciliation.
PREMIUM_LEDGER_TX_TYPES = {
    'premium_payment',
    'bill_payment',
    'bill_paid',
    'premium_received',
    'auto_pay_execution',
    'premium_deposit',
}


def get_transaction_type(tx: Dict[str, Any]) -> str:
    """Return normalized transaction type across legacy/current schemas."""
    return str(tx.get('type') or tx.get('tx_type') or '').strip().lower()


def calculate_cumulative_premium_income(exclude_suspended: bool = True) -> Dict[str, float]:
    """
    Calculate cumulative premium income with data-integrity safeguards.

    Sources:
    1) Paid bill amounts (authoritative for billed premium collections)
    2) Unbilled premium ledger amounts (direct premium payments/prepayments)
    """
    bill_paid_total = 0.0
    paid_bills_count = 0
    paid_bill_ids = set()

    for bill_id, bill in BILLING.items():
        customer_id = bill.get('customer_id', '')
        if exclude_suspended and is_suspended_account(customer_id):
            continue

        amount_paid = safe_float(bill.get('amount_paid', 0))
        if amount_paid <= 0:
            continue

        bill_paid_total += amount_paid
        paid_bills_count += 1
        paid_bill_ids.add(str(bill.get('id') or bill_id))

    ledger_unbilled_total = 0.0
    ledger_unbilled_count = 0

    for tx in TRANSACTION_LEDGER.values():
        tx_type = get_transaction_type(tx)
        if tx_type not in PREMIUM_LEDGER_TX_TYPES:
            continue

        customer_id = tx.get('customer_id', '')
        if exclude_suspended and is_suspended_account(customer_id):
            continue

        amount = safe_float(tx.get('amount', 0))
        if amount <= 0:
            continue

        metadata = tx.get('metadata', {})
        if not isinstance(metadata, dict):
            metadata = {}

        linked_bill_id = str(metadata.get('bill_id') or '').strip()
        # If already captured by a paid bill, don't count it again.
        if linked_bill_id and linked_bill_id in paid_bill_ids:
            continue

        # For customer premium payments, include only explicitly unbilled
        # remainder when available to avoid double counting with BILLING.
        if tx_type == 'premium_payment' and metadata.get('unbilled_premium_amount') is not None:
            amount = safe_float(metadata.get('unbilled_premium_amount', 0))

        if amount <= 0:
            continue

        ledger_unbilled_total += amount
        ledger_unbilled_count += 1

    total = bill_paid_total + ledger_unbilled_total
    return {
        'total': round(total, 2),
        'from_bills': round(bill_paid_total, 2),
        'ledger_unbilled_total': round(ledger_unbilled_total, 2),
        'paid_bills_count': paid_bills_count,
        'ledger_unbilled_count': ledger_unbilled_count,
    }


