def _sanitize_ascii_filename_stem(
    value: str,
    fallback: str,
    *,
    strip_chars: str,
    collapse_repeated_underscores: bool,
    max_length: Optional[int] = None,
) -> str:
    """Create a compact ASCII-safe filename stem with caller-specific cleanup."""
    value = (value or '').strip()
    if not value:
        return fallback

    safe_chars = []
    for ch in value:
        if ord(ch) < 128 and (ch.isalnum() or ch in ('-', '_')):
            safe_chars.append(ch)
        elif ch in (' ', '.'):
            safe_chars.append('_')

    cleaned = ''.join(safe_chars).strip(strip_chars)
    if collapse_repeated_underscores:
        while '__' in cleaned:
            cleaned = cleaned.replace('__', '_')
    if max_length is not None:
        cleaned = cleaned[:max_length]
    return cleaned or fallback


def safe_ascii_filename_stem(value: str, fallback: str = 'subtitle_track') -> str:
    """Create a compact ASCII-safe filename stem."""
    return _sanitize_ascii_filename_stem(
        value,
        fallback,
        strip_chars='._',
        collapse_repeated_underscores=True,
        max_length=80,
    )


def serialize_media_subtitle_track(track: Dict[str, Any]) -> Dict[str, Any]:
    """Return subtitle track metadata without embedded subtitle content."""
    return {
        'id': track.get('id'),
        'language': track.get('language', 'en'),
        'format': track.get('format', 'srt'),
        'label': track.get('label', 'Subtitles'),
        'status': track.get('status', 'completed'),
        'provider': track.get('provider', ''),
        'job_id': track.get('job_id', ''),
        'download_url': track.get('download_url', ''),
        'created_at': track.get('created_at'),
        'size': track.get('size', 0),
    }


def serialize_media_job(job: Dict[str, Any], include_callback: bool = False) -> Dict[str, Any]:
    """Return a safe media job payload for API responses."""
    payload = {
        'id': job.get('id'),
        'job_kind': job.get('job_kind', 'subtitle'),
        'asset_id': job.get('asset_id'),
        'asset_name': job.get('asset_name'),
        'provider': job.get('provider'),
        'provider_job_id': job.get('provider_job_id'),
        'language': job.get('language', 'en'),
        'status': job.get('status', 'queued'),
        'requested_at': job.get('requested_at'),
        'requested_by': job.get('requested_by'),
        'completed_at': job.get('completed_at'),
        'error': job.get('error'),
        'message': job.get('message', ''),
        'subtitle_track_id': job.get('subtitle_track_id'),
        'campaign_id': job.get('campaign_id'),
        'blueprint_index': job.get('blueprint_index'),
        'generated_asset_id': job.get('generated_asset_id'),
        'provider_operation_name': job.get('provider_operation_name', ''),
        'provider_status': job.get('provider_status', ''),
        'provider_model': job.get('provider_model', ''),
        'progress_pct': safe_int(job.get('progress_pct'), 0),
    }
    if include_callback:
        payload['callback_path'] = job.get('callback_path', '')
        payload['callback_url'] = job.get('callback_url', '')
    return payload


def serialize_media_asset(asset: Dict[str, Any]) -> Dict[str, Any]:
    """Strip internal processing secrets and subtitle payloads from media responses."""
    payload = dict(asset)
    processing = asset.get('processing')
    if isinstance(processing, dict):
        payload['processing'] = dict(processing)
    subtitles = asset.get('subtitles')
    if isinstance(subtitles, list):
        payload['subtitles'] = [
            serialize_media_subtitle_track(track)
            for track in subtitles
            if isinstance(track, dict)
        ]
    return payload


def media_asset_url(asset: Dict[str, Any]) -> str:
    """Resolve the best available playback/download URL for a media asset."""
    return str(asset.get('url') or asset.get('data') or '').strip()


def get_media_asset_playback_url(asset_id: str) -> str:
    """Return the current playable URL for a media asset, if any."""
    asset = MEDIA_ASSETS.get(asset_id)
    if not asset:
        return ''
    return media_asset_url(asset)


def ensure_media_storage_dir() -> None:
    """Create the on-disk media storage directory if it does not already exist."""
    os.makedirs(MEDIA_STORAGE_DIR, exist_ok=True)


def build_internal_media_file_url(asset_id: str, filename: str) -> str:
    """Build the internal route used to stream a stored media file."""
    safe_name = safe_ascii_filename_stem(filename or asset_id, fallback=asset_id)
    return f"/media-files/{asset_id}/{safe_name}"


def write_media_binary_payload(asset_id: str, filename: str, payload_bytes: bytes) -> str:
    """Persist heavy media bytes to disk and return the saved file path."""
    ensure_media_storage_dir()
    stem = safe_ascii_filename_stem(filename or asset_id, fallback=asset_id)
    file_path = os.path.join(MEDIA_STORAGE_DIR, f"{asset_id}-{stem}")
    with open(file_path, 'wb') as handle:
        handle.write(payload_bytes)
    return file_path


def decode_media_data_url(data_url: str) -> tuple[bytes, str]:
    """Decode a data URL into raw bytes and mime type."""
    value = str(data_url or '').strip()
    if not value.startswith('data:') or ',' not in value:
        raise ValueError('Expected a valid data URL payload')
    header, encoded = value.split(',', 1)
    mime_type = header[5:].split(';', 1)[0].strip() or 'application/octet-stream'
    if ';base64' in header:
        payload_bytes = base64.b64decode(encoded.encode('ascii'))
    else:
        payload_bytes = urlparse.unquote_to_bytes(encoded)
    return payload_bytes, mime_type


def persist_media_asset_payload(asset: Dict[str, Any]) -> Dict[str, Any]:
    """Offload heavy inline media payloads to file storage when appropriate."""
    if not isinstance(asset, dict):
        return asset
    data_url = str(asset.get('data') or '').strip()
    if not data_url:
        return asset
    try:
        payload_bytes, mime_type = decode_media_data_url(data_url)
    except Exception:
        return asset
    if len(payload_bytes) <= MEDIA_INLINE_MAX_BYTES:
        return asset

    filename = str(asset.get('name') or asset.get('id') or 'media_asset').strip() or 'media_asset'
    file_path = write_media_binary_payload(str(asset.get('id') or uuid.uuid4().hex), filename, payload_bytes)
    asset['data'] = ''
    asset['url'] = build_internal_media_file_url(str(asset.get('id') or ''), filename)
    asset['file_path'] = file_path
    asset['stored_externally'] = True
    asset['format'] = asset.get('format') or mime_type
    asset['size'] = safe_int(asset.get('size') or len(payload_bytes), len(payload_bytes))
    return asset


def get_media_subtitle_tracks(asset: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Ensure subtitle tracks are always stored as a list on the media asset."""
    tracks = asset.get('subtitles')
    if not isinstance(tracks, list):
        tracks = []
        asset['subtitles'] = tracks
    return tracks


def update_media_processing_state(asset: Dict[str, Any], job: Dict[str, Any], message: str = '') -> None:
    """Sync the current subtitle-processing summary onto the media asset."""
    asset['processing'] = {
        'subtitle_job_id': job.get('id'),
        'subtitle_status': job.get('status', 'queued'),
        'provider': job.get('provider', DEFAULT_MEDIA_SUBTITLE_PROVIDER),
        'provider_job_id': job.get('provider_job_id', ''),
        'language': job.get('language', 'en'),
        'message': message or job.get('message', ''),
        'updated_at': datetime.now().isoformat(),
        'completed_at': job.get('completed_at'),
        'subtitle_track_id': job.get('subtitle_track_id'),
    }


def chunk_transcript_words(text: str, words_per_chunk: int = 12) -> List[str]:
    """Break transcript text into subtitle-sized chunks."""
    words = [word for word in str(text or '').replace('\r', ' ').replace('\n', ' ').split() if word]
    if not words:
        return []
    return [
        ' '.join(words[index:index + words_per_chunk])
        for index in range(0, len(words), words_per_chunk)
    ]


def normalize_subtitle_segments(
    segments: Any,
    transcript_text: str = '',
    duration: Any = None,
) -> List[Dict[str, Any]]:
    """Normalize provider subtitle segments into SRT-friendly entries."""
    normalized: List[Dict[str, Any]] = []
    if isinstance(segments, list):
        last_end = 0.0
        for index, segment in enumerate(segments):
            if not isinstance(segment, dict):
                continue
            text = str(
                segment.get('text')
                or segment.get('transcript')
                or segment.get('caption')
                or ''
            ).strip()
            if not text:
                continue
            start = safe_float(segment.get('start'), last_end if index else float(index * 3))
            end = safe_float(
                segment.get('end'),
                start + max(safe_float(segment.get('duration'), 3.0), 1.5),
            )
            if end <= start:
                end = start + 1.5
            normalized.append({
                'start': round(start, 3),
                'end': round(end, 3),
                'text': text,
            })
            last_end = end
        if normalized:
            return normalized

    chunks = chunk_transcript_words(transcript_text)
    if not chunks:
        fallback_text = str(transcript_text or '').strip() or 'Subtitle transcript pending provider delivery.'
        chunks = chunk_transcript_words(fallback_text, words_per_chunk=8) or [fallback_text]

    total_duration = safe_float(duration, 0.0)
    chunk_span = max(total_duration / max(len(chunks), 1), 2.0) if total_duration > 0 else 3.0
    cursor = 0.0
    normalized = []
    for index, chunk in enumerate(chunks):
        end = cursor + chunk_span
        if total_duration > 0 and index == len(chunks) - 1:
            end = max(total_duration, cursor + 1.5)
        normalized.append({
            'start': round(cursor, 3),
            'end': round(max(end, cursor + 1.5), 3),
            'text': chunk,
        })
        cursor = end
    return normalized


def format_srt_timestamp(seconds: Any) -> str:
    """Convert seconds into SRT hh:mm:ss,mmm format."""
    total_ms = max(int(round(safe_float(seconds, 0.0) * 1000)), 0)
    hours, remainder = divmod(total_ms, 3600000)
    minutes, remainder = divmod(remainder, 60000)
    secs, milliseconds = divmod(remainder, 1000)
    return f"{hours:02d}:{minutes:02d}:{secs:02d},{milliseconds:03d}"


def generate_srt_content(segments: List[Dict[str, Any]]) -> str:
    """Render normalized subtitle segments into an SRT document."""
    lines: List[str] = []
    for index, segment in enumerate(segments, start=1):
        lines.append(str(index))
        lines.append(
            f"{format_srt_timestamp(segment.get('start'))} --> "
            f"{format_srt_timestamp(segment.get('end'))}"
        )
        lines.append(str(segment.get('text') or '').strip() or '...')
        lines.append('')
    return '\n'.join(lines).strip() + '\n'


def upsert_media_subtitle_track(asset: Dict[str, Any], track: Dict[str, Any]) -> Dict[str, Any]:
    """Insert or replace a subtitle track on a media asset."""
    tracks = get_media_subtitle_tracks(asset)
    for index, existing in enumerate(tracks):
        if isinstance(existing, dict) and existing.get('id') == track.get('id'):
            tracks[index] = track
            return track
    tracks.insert(0, track)
    return track


def find_media_processing_job(job_id: str = '', provider_job_id: str = '') -> Optional[Dict[str, Any]]:
    """Look up a media processing job by internal or provider job id."""
    if job_id and job_id in MEDIA_PROCESSING_JOBS:
        return MEDIA_PROCESSING_JOBS[job_id]
    if provider_job_id:
        for job in MEDIA_PROCESSING_JOBS.values():
            if job.get('provider_job_id') == provider_job_id:
                return job
    return None


def list_media_processing_jobs_for_campaign(campaign_id: str, job_kind: str = '') -> List[Dict[str, Any]]:
    """Return media processing jobs associated with a campaign."""
    items: List[Dict[str, Any]] = []
    for job in MEDIA_PROCESSING_JOBS.values():
        if not isinstance(job, dict):
            continue
        if campaign_id and str(job.get('campaign_id') or '') != campaign_id:
            continue
        if job_kind and str(job.get('job_kind') or '') != job_kind:
            continue
        items.append(job)
    items.sort(key=lambda item: item.get('requested_at', ''), reverse=True)
    return items


def marketing_state_dict() -> Dict[str, Any]:
    """Ensure marketing sales agent state is always a mutable dict."""
    state = DESIGN_SETTINGS.setdefault('marketing_sales_agent', {})
    if not isinstance(state, dict):
        state = {}
        DESIGN_SETTINGS['marketing_sales_agent'] = state
    return state


def marketing_campaign_record_for_response(record: Dict[str, Any]) -> Dict[str, Any]:
    """Return a response-safe marketing campaign record copy."""
    payload = dict(record) if isinstance(record, dict) else {}
    payload['campaign'] = dict(payload.get('campaign') or {})
    payload['integrity'] = dict(payload.get('integrity') or {})
    payload['assets_created'] = list(payload.get('assets_created') or [])
    return payload


def get_current_marketing_campaign_record() -> Dict[str, Any]:
    """Return the latest published campaign, or the latest validated draft if no publish exists yet."""
    marketing_state = marketing_state_dict()
    latest_campaign = marketing_state.get('latest_campaign')
    if isinstance(latest_campaign, dict) and isinstance(latest_campaign.get('campaign'), dict):
        return latest_campaign

    generated_draft = marketing_state.get('generated_campaign')
    if isinstance(generated_draft, dict) and isinstance(generated_draft.get('campaign'), dict):
        return generated_draft
    return {}


def store_generated_marketing_campaign(*, generated: Dict[str, Any], generated_by: str) -> Dict[str, Any]:
    """Persist the latest generated marketing campaign as a validated draft."""
    marketing_state = marketing_state_dict()
    campaign_payload = dict(generated.get('campaign') or {})
    integrity_payload = dict(generated.get('integrity') or {})
    generated_at = datetime.now().isoformat()
    draft_record = {
        'campaign': campaign_payload,
        'integrity': integrity_payload,
        'assets_created': [],
        'generated_at': generated_at,
        'generated_by': generated_by or 'admin',
        'status': 'generated',
    }
    marketing_state['generated_campaign'] = draft_record
    marketing_state['updated_at'] = generated_at
    marketing_state['updated_by'] = generated_by or 'admin'
    DESIGN_SETTINGS['marketing_sales_agent'] = marketing_state
    DESIGN_SETTINGS['updated_at'] = generated_at
    DESIGN_SETTINGS['updated_by'] = generated_by or 'admin'
    return draft_record


def get_media_subtitle_track(asset: Dict[str, Any], track_id: str = '') -> Optional[Dict[str, Any]]:
    """Return the requested subtitle track, or the most recent one if no id is provided."""
    tracks = get_media_subtitle_tracks(asset)
    if track_id:
        for track in tracks:
            if isinstance(track, dict) and track.get('id') == track_id:
                return track
        return None
    return tracks[0] if tracks else None


def build_media_subtitle_download_url(asset_id: str, track_id: str) -> str:
    """Return the authenticated download route for an SRT track."""
    return f"/api/media/{asset_id}/download/srt?track_id={track_id}"


def create_media_subtitle_job(
    asset: Dict[str, Any],
    requested_by: str,
    language: str,
    provider: str,
    callback_base_url: str = '',
) -> Dict[str, Any]:
    """Create a queued subtitle job for a video asset."""
    job_id = f"mjob-{uuid.uuid4().hex[:12]}"
    provider_job_id = f"prov-{uuid.uuid4().hex[:12]}"
    callback_token = secrets.token_urlsafe(18)
    callback_path = f"/api/provider/media-processing/callback?job_id={job_id}&token={callback_token}"
    callback_url = f"{callback_base_url.rstrip('/')}{callback_path}" if callback_base_url else callback_path
    requested_at = datetime.now().isoformat()
    job = {
        'id': job_id,
        'asset_id': asset.get('id'),
        'asset_name': asset.get('name', 'Untitled Video'),
        'provider': provider or DEFAULT_MEDIA_SUBTITLE_PROVIDER,
        'provider_job_id': provider_job_id,
        'callback_token': callback_token,
        'callback_path': callback_path,
        'callback_url': callback_url,
        'language': language or 'en',
        'status': 'queued',
        'requested_at': requested_at,
        'requested_by': requested_by or 'admin',
        'completed_at': None,
        'error': None,
        'message': 'Queued with provider. Awaiting completion webhook.',
        'subtitle_track_id': None,
    }
    MEDIA_PROCESSING_JOBS[job_id] = job
    update_media_processing_state(asset, job, job['message'])
    return job


def build_media_subtitle_track(
    asset: Dict[str, Any],
    job: Dict[str, Any],
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    """Build a stored subtitle track from provider payload or transcript text."""
    language = str(payload.get('language') or job.get('language') or 'en').strip().lower() or 'en'
    transcript_text = str(
        payload.get('transcript')
        or payload.get('transcript_text')
        or payload.get('text')
        or payload.get('full_text')
        or ''
    ).strip()
    normalized_segments = normalize_subtitle_segments(
        payload.get('segments') or payload.get('subtitles') or payload.get('captions'),
        transcript_text=transcript_text,
        duration=payload.get('duration') or asset.get('duration'),
    )
    srt_content = str(payload.get('srt') or payload.get('subtitle_content') or '').strip()
    if not srt_content:
        srt_content = generate_srt_content(normalized_segments)
    if not srt_content.endswith('\n'):
        srt_content += '\n'

    track_id = str(job.get('subtitle_track_id') or f"sub-{uuid.uuid4().hex[:12]}")
    filename_stem = safe_ascii_filename_stem(
        f"{asset.get('name') or asset.get('id') or 'video'}_{language}",
        fallback='subtitle_track',
    )
    created_at = datetime.now().isoformat()
    return {
        'id': track_id,
        'language': language,
        'format': 'srt',
        'label': str(payload.get('label') or f"{language.upper()} Subtitles"),
        'status': 'completed',
        'provider': job.get('provider', DEFAULT_MEDIA_SUBTITLE_PROVIDER),
        'job_id': job.get('id'),
        'download_url': build_media_subtitle_download_url(asset.get('id', ''), track_id),
        'filename': f"{filename_stem}.srt",
        'size': len(srt_content.encode('utf-8')),
        'created_at': created_at,
        'content': srt_content,
        'segments': normalized_segments,
        'transcript_text': transcript_text,
    }


def complete_media_subtitle_job(job: Dict[str, Any], payload: Dict[str, Any]) -> Tuple[Optional[Dict[str, Any]], Optional[Dict[str, Any]]]:
    """Finalize a queued subtitle job from a provider webhook payload."""
    asset_id = str(job.get('asset_id') or '')
    asset = MEDIA_ASSETS.get(asset_id)
    if not asset:
        job['status'] = 'failed'
        job['completed_at'] = datetime.now().isoformat()
        job['error'] = 'Media asset missing during callback finalization'
        job['message'] = 'Provider callback received after media asset was removed.'
        save_ledger_data()
        return None, None

    provider_job_id = str(payload.get('provider_job_id') or '').strip()
    if provider_job_id:
        job['provider_job_id'] = provider_job_id

    status_value = str(payload.get('status') or payload.get('state') or 'completed').strip().lower()
    if status_value in {'failed', 'error', 'cancelled'}:
        job['status'] = 'failed'
        job['completed_at'] = datetime.now().isoformat()
        job['error'] = str(payload.get('error') or payload.get('message') or 'Provider reported failure')
        job['message'] = job['error']
        update_media_processing_state(asset, job, job['message'])
        save_ledger_data()
        return asset, None

    track = build_media_subtitle_track(asset, job, payload)
    upsert_media_subtitle_track(asset, track)
    job['status'] = 'completed'
    job['completed_at'] = datetime.now().isoformat()
    job['error'] = None
    job['message'] = str(payload.get('message') or 'Subtitle track completed and ready for download.')
    job['subtitle_track_id'] = track.get('id')
    update_media_processing_state(asset, job, job['message'])
    save_ledger_data()
    return asset, track


def verify_media_provider_callback(headers: Any, raw_body: bytes, payload: Dict[str, Any]) -> bool:
    """Accept either shared-secret or HMAC-signed provider callbacks."""
    provided_secret = (
        headers.get('X-Media-Webhook-Secret')
        or headers.get('X-Webhook-Secret')
        or payload.get('webhook_secret')
        or payload.get('secret')
    )
    if provided_secret and secrets.compare_digest(str(provided_secret), str(MEDIA_PROVIDER_WEBHOOK_SECRET)):
        return True

    auth_header = str(headers.get('Authorization') or '')
    if auth_header.startswith('Bearer '):
        bearer_secret = auth_header.split(' ', 1)[1].strip()
        if bearer_secret and secrets.compare_digest(bearer_secret, str(MEDIA_PROVIDER_WEBHOOK_SECRET)):
            return True

    provided_signature = str(
        headers.get('X-Media-Signature')
        or headers.get('X-Webhook-Signature')
        or payload.get('signature')
        or ''
    ).strip()
    if provided_signature:
        if provided_signature.lower().startswith('sha256='):
            provided_signature = provided_signature.split('=', 1)[1].strip()
        expected_signature = hmac.new(
            str(MEDIA_PROVIDER_WEBHOOK_SECRET).encode('utf-8'),
            raw_body,
            hashlib.sha256,
        ).hexdigest()
        return hmac.compare_digest(provided_signature, expected_signature)

    return False


def update_video_generation_job_state(job: Dict[str, Any], payload: Dict[str, Any]) -> None:
    """Normalize provider job state onto a video generation job record."""
    if not isinstance(payload, dict):
        return
    job['provider_status'] = str(payload.get('status') or job.get('provider_status') or '').strip().lower()
    progress_value = payload.get('progress_pct')
    if progress_value is not None:
        job['progress_pct'] = max(0, min(100, safe_int(progress_value, safe_int(job.get('progress_pct'), 0))))
    if payload.get('provider_job_id'):
        job['provider_job_id'] = str(payload.get('provider_job_id'))
    if payload.get('provider_state') is not None:
        job['provider_state'] = payload.get('provider_state')
    if payload.get('download_url'):
        job['download_url'] = str(payload.get('download_url')).strip()
    if payload.get('message'):
        job['message'] = str(payload.get('message'))
    if payload.get('error'):
        job['error'] = str(payload.get('error'))


def create_media_video_job(
    *,
    campaign_id: str,
    blueprint_index: int,
    blueprint: Dict[str, Any],
    requested_by: str,
    provider: str,
    callback_base_url: str = '',
    provider_model: str = '',
    image_data_url: str = '',
    auto_publish_to_hero: bool = False,
    prompt_override: str = '',
) -> Dict[str, Any]:
    """Create and submit a provider-backed video generation job."""
    service = get_media_generation_service()
    prompt_override = str(prompt_override or '').strip()
    prompt_parts = [
        prompt_override,
        str(blueprint.get('title') or '').strip(),
        str(blueprint.get('format') or '').strip(),
        str(blueprint.get('voiceover_style') or '').strip(),
    ]
    storyboard = blueprint.get('storyboard') or []
    if isinstance(storyboard, list) and storyboard:
        prompt_parts.append('Storyboard: ' + ' '.join(str(item).strip() for item in storyboard if str(item).strip()))
    prompt = '. '.join(part for part in prompt_parts if part)
    if not prompt:
        prompt = f"Marketing video for campaign {campaign_id}"

    aspect_ratio = '16:9'
    format_hint = str(blueprint.get('format') or '').lower()
    if 'vertical' in format_hint or 'short' in format_hint or 'reel' in format_hint:
        aspect_ratio = '9:16'

    submission = service.submit_video_generation(
        provider=provider,
        prompt=prompt,
        title=str(blueprint.get('title') or f'{campaign_id} Video {blueprint_index + 1}'),
        model=provider_model,
        aspect_ratio=aspect_ratio,
        duration_seconds=8,
        resolution='720p',
        image_data_url=image_data_url,
        callback_url=f"{callback_base_url.rstrip('/')}/api/provider/media-processing/callback" if callback_base_url else '',
        metadata={
            'campaign_id': campaign_id,
            'blueprint_index': blueprint_index,
            'requested_by': requested_by,
        },
    )

    requested_at = datetime.now().isoformat()
    job_id = f"mjob-{uuid.uuid4().hex[:12]}"
    callback_token = secrets.token_urlsafe(18)
    callback_path = f"/api/provider/media-processing/callback?job_id={job_id}&token={callback_token}"
    callback_url = f"{callback_base_url.rstrip('/')}{callback_path}" if callback_base_url else callback_path
    job = {
        'id': job_id,
        'job_kind': 'video_generation',
        'campaign_id': campaign_id,
        'blueprint_index': blueprint_index,
        'blueprint_snapshot': dict(blueprint) if isinstance(blueprint, dict) else {},
        'asset_id': '',
        'asset_name': str(blueprint.get('title') or f'{campaign_id} Video {blueprint_index + 1}'),
        'provider': provider,
        'provider_job_id': str(submission.get('provider_job_id') or ''),
        'provider_operation_name': str((submission.get('provider_state') or {}).get('operation_name') or ''),
        'provider_status': str(submission.get('status') or 'queued'),
        'provider_state': submission.get('provider_state') or {},
        'provider_model': provider_model or '',
        'image_data_url': image_data_url or '',
        'prompt_override': prompt_override,
        'language': 'en',
        'status': 'queued',
        'progress_pct': 5,
        'requested_at': requested_at,
        'requested_by': requested_by or 'admin',
        'completed_at': None,
        'error': None,
        'message': str(submission.get('message') or 'Video generation submitted to provider.'),
        'subtitle_track_id': None,
        'generated_asset_id': '',
        'download_url': '',
        'auto_publish_to_hero': bool(auto_publish_to_hero),
        'callback_token': callback_token,
        'callback_path': callback_path,
        'callback_url': callback_url,
    }
    MEDIA_PROCESSING_JOBS[job_id] = job
    return job


def cancel_media_video_job(job: Dict[str, Any], cancelled_by: str) -> Dict[str, Any]:
    """Mark a queued or processing video job as cancelled."""
    job['status'] = 'cancelled'
    job['provider_status'] = 'cancelled'
    job['completed_at'] = datetime.now().isoformat()
    job['message'] = f"Cancelled by {cancelled_by or 'admin'}."
    job['error'] = None
    job['progress_pct'] = safe_int(job.get('progress_pct'), 0)
    return job


def build_video_job_reference_image_data_url(asset_id: str) -> str:
    """Resolve a PHINS media image asset into a data/url payload for image-to-video."""
    asset = MEDIA_ASSETS.get(asset_id)
    if not asset or asset.get('type') != 'image':
        return ''
    return str(asset.get('data') or asset.get('url') or '').strip()


def finalize_media_video_job(job: Dict[str, Any], poll_result: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Download a completed provider video and store it as a media asset."""
    from services.media_generation_service import MediaGenerationError

    if not isinstance(job, dict):
        return None

    update_video_generation_job_state(job, poll_result)
    status_value = str(poll_result.get('status') or '').strip().lower()
    if status_value == 'processing':
        job['status'] = 'processing'
        job['progress_pct'] = max(safe_int(job.get('progress_pct'), 5), safe_int(poll_result.get('progress_pct'), 45))
        return None
    if status_value == 'failed':
        job['status'] = 'failed'
        job['progress_pct'] = safe_int(poll_result.get('progress_pct'), safe_int(job.get('progress_pct'), 0))
        job['completed_at'] = datetime.now().isoformat()
        job['error'] = str(poll_result.get('error') or 'Provider video generation failed')
        return None

    download_url = str(poll_result.get('download_url') or '').strip()
    if not download_url:
        job['status'] = 'failed'
        job['completed_at'] = datetime.now().isoformat()
        job['error'] = 'Provider completed without a downloadable video URL'
        return None

    service = get_media_generation_service()
    try:
        downloaded = service.download_generated_video(provider=str(job.get('provider') or ''), download_url=download_url)
    except MediaGenerationError as exc:
        job['status'] = 'failed'
        job['completed_at'] = datetime.now().isoformat()
        job['error'] = str(exc)
        return None

    campaign_id = str(job.get('campaign_id') or 'MKT-UNKNOWN')
    asset_id = f"media-{uuid.uuid4().hex[:12]}"
    uploaded_at = datetime.now().isoformat()
    asset = {
        'id': asset_id,
        'name': f"{job.get('asset_name') or campaign_id}.mp4",
        'type': 'video',
        'format': str(downloaded.get('content_type') or 'video/mp4'),
        'size': safe_int(downloaded.get('size'), 0),
        'url': '',
        'data': str(downloaded.get('data_url') or ''),
        'thumbnail': str(job.get('thumbnail_url') or ''),
        'duration': safe_int(poll_result.get('duration') or 8, 8),
        'source': 'ai_video_generation',
        'uploaded_at': uploaded_at,
        'uploaded_by': str(job.get('requested_by') or 'admin'),
        'metadata': {
            'campaign_id': campaign_id,
            'job_id': job.get('id'),
            'provider': job.get('provider'),
            'blueprint_index': job.get('blueprint_index'),
            'generated_from': 'marketing_video_blueprint',
        }
    }
    asset = persist_media_asset_payload(asset)
    MEDIA_ASSETS[asset_id] = asset
    job['generated_asset_id'] = asset_id
    job['status'] = 'completed'
    job['progress_pct'] = 100
    job['completed_at'] = uploaded_at
    job['error'] = None
    job['message'] = str(poll_result.get('message') or 'Generated video saved to media library.')
    job['download_url'] = download_url
    if job.get('auto_publish_to_hero'):
        DESIGN_SETTINGS['hero_video_id'] = asset_id
        DESIGN_SETTINGS['video_url'] = media_asset_url(asset)
        DESIGN_SETTINGS['video_poster'] = asset.get('thumbnail', '')
        DESIGN_SETTINGS['video_poster_id'] = ''
        DESIGN_SETTINGS['updated_at'] = uploaded_at
        DESIGN_SETTINGS['updated_by'] = str(job.get('requested_by') or 'admin')
    return asset


def poll_and_finalize_media_video_job(job_id: str) -> None:
    """Poll a provider-backed video generation job and finalize it if ready."""
    from services.media_generation_service import MediaGenerationError

    job = MEDIA_PROCESSING_JOBS.get(job_id)
    if not isinstance(job, dict):
        return
    if str(job.get('job_kind') or '') != 'video_generation':
        return
    if str(job.get('status') or '') in {'completed', 'failed'}:
        return

    service = get_media_generation_service()
    try:
        poll_result = service.poll_video_generation(
            provider=str(job.get('provider') or ''),
            provider_job_id=str(job.get('provider_job_id') or ''),
            provider_state=job.get('provider_state') if isinstance(job.get('provider_state'), dict) else {},
        )
        update_video_generation_job_state(job, poll_result)
        finalize_media_video_job(job, poll_result)
    except MediaGenerationError as exc:
        job['status'] = 'failed'
        job['completed_at'] = datetime.now().isoformat()
        job['error'] = str(exc)
        job['message'] = str(exc)
    finally:
        save_ledger_data()


def start_media_job_polling(job_id: str, delay_seconds: int = 5) -> None:
    """Poll a media generation job in the background once after a short delay."""
    wait_seconds = max(safe_int(delay_seconds, 5), 1)

    def _runner() -> None:
        time.sleep(wait_seconds)
        poll_and_finalize_media_video_job(job_id)

    threading.Thread(target=_runner, daemon=True).start()


def video_generation_jobs_for_campaign_response(campaign_id: str) -> List[Dict[str, Any]]:
    """Serialize video generation jobs for a campaign."""
    return [
        serialize_media_job(job, include_callback=True)
        for job in list_media_processing_jobs_for_campaign(campaign_id, job_kind='video_generation')
    ]


def resolve_media_video_job_image_data_url(payload: Dict[str, Any]) -> str:
    """Resolve the request's explicit or referenced image payload for video generation."""
    image_data_url = str(payload.get('image_data_url') or '').strip()
    if image_data_url:
        return image_data_url

    reference_image_asset_id = str(payload.get('reference_image_asset_id') or '').strip()
    if not reference_image_asset_id:
        return ''
    return build_video_job_reference_image_data_url(reference_image_asset_id)


def latest_campaign_video_blueprints(campaign_id: str) -> Tuple[Dict[str, Any], List[Dict[str, Any]], str]:
    """Return stored campaign video blueprints for the requested campaign."""
    campaign_record = get_current_marketing_campaign_record()
    campaign_payload = campaign_record.get('campaign') if isinstance(campaign_record, dict) else {}
    if not isinstance(campaign_payload, dict):
        campaign_payload = {}
    if str(campaign_payload.get('campaign_id') or '') != campaign_id:
        return {}, [], 'Campaign not found or not loaded as latest campaign'

    blueprints = campaign_payload.get('ai_video_blueprints')
    if not isinstance(blueprints, list) or not blueprints:
        return campaign_payload, [], 'Video blueprint not found'
    return campaign_payload, blueprints, ''


def request_campaign_video_blueprints(campaign_id: str, request_payload: Dict[str, Any]) -> Tuple[Dict[str, Any], List[Dict[str, Any]], str]:
    """Validate and return a signed preview campaign payload from the request body."""
    campaign_payload = request_payload.get('campaign_payload')
    if not isinstance(campaign_payload, dict):
        return {}, [], 'Campaign not found or not loaded as latest campaign'
    if str(campaign_payload.get('campaign_id') or '').strip() != campaign_id:
        return {}, [], 'Campaign payload does not match requested campaign_id'

    integrity_payload = request_payload.get('campaign_integrity')
    if not isinstance(integrity_payload, dict):
        return {}, [], 'Campaign integrity is required for unpublished campaign video generation'

    signature = str(integrity_payload.get('signature') or '').strip()
    if not signature:
        return {}, [], 'Campaign integrity signature is required for unpublished campaign video generation'

    from services.marketing_sales_agent_service import get_marketing_sales_agent_service

    service = get_marketing_sales_agent_service()
    if not service.verify_campaign_payload(campaign_payload, signature):
        return {}, [], 'Campaign payload failed integrity verification'

    blueprints = campaign_payload.get('ai_video_blueprints')
    if not isinstance(blueprints, list) or not blueprints:
        return campaign_payload, [], 'Video blueprint not found'
    return campaign_payload, blueprints, ''


def resolve_media_video_job_blueprints(campaign_id: str, request_payload: Optional[Dict[str, Any]] = None) -> Tuple[Dict[str, Any], List[Dict[str, Any]], str]:
    """Resolve video blueprints from the published campaign or a verified preview payload."""
    campaign_payload, blueprints, error = latest_campaign_video_blueprints(campaign_id)
    if not error:
        return campaign_payload, blueprints, ''

    if not isinstance(request_payload, dict):
        return {}, [], error
    if not isinstance(request_payload.get('campaign_payload'), dict):
        return {}, [], error

    return request_campaign_video_blueprints(campaign_id, request_payload)


def retry_media_video_job(job: Dict[str, Any], *, requested_by: str, callback_base_url: str = '') -> Dict[str, Any]:
    """Create a fresh job using the original job's blueprint/provider settings."""
    campaign_id = str(job.get('campaign_id') or '')
    blueprint_index = safe_int(job.get('blueprint_index'), -1)
    if not campaign_id or blueprint_index < 0:
        raise ValueError('Retry requested for a job without campaign blueprint context')

    _, blueprints, error = latest_campaign_video_blueprints(campaign_id)
    if not error and blueprint_index < len(blueprints):
        blueprint = blueprints[blueprint_index]
    else:
        blueprint = job.get('blueprint_snapshot') if isinstance(job.get('blueprint_snapshot'), dict) else {}
        if not blueprint:
            raise ValueError('Current campaign no longer matches the job blueprint context')

    return create_media_video_job(
        campaign_id=campaign_id,
        blueprint_index=blueprint_index,
        blueprint=blueprint,
        requested_by=requested_by,
        provider=str(job.get('provider') or DEFAULT_MEDIA_VIDEO_PROVIDER),
        callback_base_url=callback_base_url,
        provider_model=str(job.get('provider_model') or ''),
        image_data_url=str(job.get('image_data_url') or ''),
        auto_publish_to_hero=bool(job.get('auto_publish_to_hero')),
        prompt_override=str(job.get('prompt_override') or ''),
    )


def generate_video_thumbnail(asset: Dict[str, Any]) -> str:
    """Generate a lightweight inline SVG thumbnail marker for generated videos."""
    title = safe_ascii_filename_stem(str(asset.get('name') or 'Generated Video'), fallback='Generated Video').replace('_', ' ')
    svg = (
        "<svg xmlns='http://www.w3.org/2000/svg' width='1280' height='720' viewBox='0 0 1280 720'>"
        "<defs><linearGradient id='g' x1='0%' y1='0%' x2='100%' y2='100%'>"
        "<stop offset='0%' stop-color='#1e3a8a'/><stop offset='100%' stop-color='#7c3aed'/>"
        "</linearGradient></defs>"
        "<rect width='1280' height='720' fill='url(#g)'/>"
        "<circle cx='640' cy='360' r='110' fill='rgba(255,255,255,0.18)'/>"
        "<polygon points='610,300 610,420 720,360' fill='white'/>"
        f"<text x='640' y='600' fill='white' font-size='42' text-anchor='middle' font-family='Arial, sans-serif'>{title[:42]}</text>"
        "</svg>"
    )
    encoded = base64.b64encode(svg.encode('utf-8')).decode('ascii')
    return f"data:image/svg+xml;base64,{encoded}"


def attach_generated_video_thumbnail(asset: Dict[str, Any]) -> None:
    """Populate thumbnail and poster fields for generated videos."""
    thumbnail = generate_video_thumbnail(asset)
    asset['thumbnail'] = thumbnail
    metadata = asset.get('metadata')
    if not isinstance(metadata, dict):
        metadata = {}
        asset['metadata'] = metadata
    metadata['generated_poster'] = thumbnail


