def _generate_bi_insights(
    doc_type: str,
    entity_type: str,
    risk_level: str,
    flags: list,
) -> Dict[str, Any]:
    """Generate actuarial / claims / billing BI insights for a document analysis."""
    insights: Dict[str, Any] = {
        'actuarial_impact': None,
        'claims_impact': None,
        'billing_impact': None,
    }

    if doc_type == 'medical' or entity_type == 'underwriting':
        loading_map = {
            'very_high': '+50% to +75%',
            'high': '+25% to +50%',
            'medium': '+10% to +25%',
            'low': 'Standard',
        }
        insights['actuarial_impact'] = {
            'premium_loading': loading_map.get(risk_level, 'Standard'),
            'underwriting_action': (
                'Decline' if risk_level == 'very_high'
                else ('Conditional Approval' if risk_level in ('high', 'medium') else 'Approve')
            ),
            'reserve_recommendation': (
                'Increase reserve' if risk_level in ('very_high', 'high') else 'Standard reserve'
            ),
        }

    if doc_type == 'authority' or entity_type == 'claim':
        if 'DEATH_CERTIFICATE' in flags:
            insights['claims_impact'] = {
                'claim_type': 'Life / Death Benefit',
                'priority': 'HIGH',
                'action': (
                    'Initiate payout process'
                    if 'AUTHENTICITY_VERIFIED' in flags
                    else 'Hold — additional verification required'
                ),
                'estimated_payout': 'Per policy sum insured',
            }
        elif 'DISABILITY_CERTIFICATE' in flags:
            insights['claims_impact'] = {
                'claim_type': 'Disability Benefit',
                'priority': 'MEDIUM-HIGH',
                'action': (
                    'Evaluate disability grade against policy terms'
                    if 'AUTHENTICITY_VERIFIED' in flags
                    else 'Hold — verification required'
                ),
                'estimated_payout': 'Per disability grade percentage of sum insured',
            }

    if doc_type == 'receipt' or entity_type in ('billing', 'policy'):
        insights['billing_impact'] = {
            'status': 'Anomaly detected' if 'BILLING_ANOMALY_OVERDUE' in flags else 'Normal',
            'action': (
                'Send overdue reminder and apply late fee'
                if 'BILLING_ANOMALY_OVERDUE' in flags
                else 'No action required'
            ),
            'large_transaction_flag': 'LARGE_TRANSACTION_DETECTED' in flags,
        }

    return insights


def analyze_document_content(doc: Dict[str, Any]) -> Dict[str, Any]:
    """AI Document Analysis Engine for PHINS.

    Performs rule-based AI analysis on an insurance document and returns structured
    findings covering actuarial underwriting risk, claims investigation
    (death / disability certificate authenticity), and billing anomaly detection.

    Returned dict keys:
        risk_level       : 'low' | 'medium' | 'high' | 'very_high'
        risk_score       : float 0–1
        flags            : list[str]  — machine-readable event labels
        findings         : list[str]  — human-readable sentences
        recommendation   : str        — suggested next action
        bi_insights      : dict       — actuarial / claims / billing metrics
        confidence       : float
        analyzed_at      : ISO-8601 timestamp
        analysis_version : str
        analysis_mode    : str
    """
    import base64 as _b64
    import re

    doc_type = doc.get('document_type', 'general')
    doc_name = (doc.get('name') or '').lower()
    description = (doc.get('description') or '').lower()
    entity_type = doc.get('entity_type', 'general')

    # Decode base64 content for keyword inspection (text-based files only)
    text_content = ''
    raw_data = doc.get('data', '')
    if raw_data:
        try:
            text_content = _b64.b64decode(raw_data).decode('utf-8', errors='ignore').lower()
        except Exception:
            text_content = ''

    full_text = f"{doc_name} {description} {text_content}"

    flags: list = []
    findings: list = []
    risk_score = 0.0

    # ── Medical / Underwriting analysis ─────────────────────────────────────
    if doc_type == 'medical' or entity_type == 'underwriting':
        if any(kw in full_text for kw in [
            'terminal', 'death', 'died', 'fatal', 'deceased',
            'mortality', 'end-of-life', 'hospice', 'palliative',
        ]):
            flags.append('TERMINAL_CONDITION_DETECTED')
            findings.append(
                'Terminal or death-related indicators found — life policy risk is VERY HIGH.'
            )
            risk_score = max(risk_score, 0.95)

        if any(kw in full_text for kw in [
            'cancer', 'tumor', 'stage 4', 'stage iv', 'hiv', 'aids',
            'stroke', 'heart failure', 'cardiac arrest', 'organ failure',
        ]):
            flags.append('SERIOUS_ILLNESS_DETECTED')
            findings.append(
                'Serious illness marker detected (cancer/cardiac/etc.) — significant premium loading required.'
            )
            risk_score = max(risk_score, 0.80)

        if any(kw in full_text for kw in [
            'disability', 'disabled', 'paralysis', 'amputation',
            'loss of limb', 'loss of sight', 'permanent partial',
        ]):
            flags.append('DISABILITY_CONDITION_DETECTED')
            findings.append(
                'Disability condition detected — evaluate disability coverage eligibility.'
            )
            risk_score = max(risk_score, 0.75)

        if any(kw in full_text for kw in [
            'diabetes', 'hypertension', 'chronic', 'smoker', 'obesity', 'bmi',
        ]):
            flags.append('CHRONIC_CONDITION_DETECTED')
            findings.append(
                'Chronic health conditions present — standard premium loading 20–35% recommended.'
            )
            risk_score = max(risk_score, 0.55)

        if 'very high risk' in full_text or 'high risk' in full_text:
            flags.append('EXPLICIT_HIGH_RISK_FLAG')
            findings.append('Document explicitly states a HIGH RISK classification.')
            risk_score = max(risk_score, 0.85)

        if not findings:
            findings.append('No elevated risk markers detected in medical documentation.')
            risk_score = max(risk_score, 0.25)

    # ── Authority certificate analysis (death / disability) ─────────────────
    if doc_type == 'authority':
        # Death certificate
        if any(kw in full_text for kw in [
            'certificate of death', 'death certificate', 'cause of death', 'died on',
        ]):
            flags.append('DEATH_CERTIFICATE')
            findings.append(
                'Death certificate identified — life insurance claim processing should be triggered.'
            )
            risk_score = max(risk_score, 0.90)
            auth_markers = [
                'ministry', 'registrar', 'authorized', 'certificate no', 'official', 'issued by',
            ]
            auth_count = sum(1 for m in auth_markers if m in full_text)
            if auth_count >= 3:
                flags.append('AUTHENTICITY_VERIFIED')
                findings.append(
                    f'Certificate authenticity: GENUINE ({auth_count}/6 official markers present).'
                )
            elif auth_count >= 1:
                flags.append('AUTHENTICITY_REQUIRES_INQUIRY')
                findings.append(
                    f'Partial authenticity markers ({auth_count}/6) — REQUIRES FURTHER INQUIRY before claim approval.'
                )
            else:
                flags.append('AUTHENTICITY_UNVERIFIABLE')
                findings.append(
                    'No official authenticity markers found — REQUIRES MANUAL VERIFICATION.'
                )

        # Disability certificate
        elif any(kw in full_text for kw in [
            'disability certificate', 'certificate of disability',
            'disability grade', 'permanent partial', 'national insurance',
        ]):
            flags.append('DISABILITY_CERTIFICATE')
            findings.append(
                'Disability certificate identified — disability benefit processing should be triggered.'
            )
            risk_score = max(risk_score, 0.80)
            auth_markers = [
                'national insurance', 'authorized', 'certificate no',
                'medical examiner', 'valid until', 'issued by',
            ]
            auth_count = sum(1 for m in auth_markers if m in full_text)
            if auth_count >= 3:
                flags.append('AUTHENTICITY_VERIFIED')
                findings.append(
                    f'Disability certificate appears GENUINE ({auth_count}/6 official markers present).'
                )
            else:
                flags.append('AUTHENTICITY_REQUIRES_INQUIRY')
                findings.append(
                    f'Only {auth_count}/6 authenticity markers present — REQUIRES FURTHER INQUIRY.'
                )
        else:
            flags.append('MANUAL_REVIEW_REQUIRED')
            findings.append(
                'Authority certificate type not definitively identified — manual classification required.'
            )
            risk_score = max(risk_score, 0.50)

    # ── Billing / receipt analysis ───────────────────────────────────────────
    if doc_type == 'receipt' or entity_type in ('billing', 'policy'):
        if any(kw in full_text for kw in [
            'overdue', 'outstanding', 'late fee', 'delinquent', 'past due',
        ]):
            flags.append('BILLING_ANOMALY_OVERDUE')
            findings.append(
                'Overdue / outstanding payment indicators detected — billing attention required.'
            )
            risk_score = max(risk_score, 0.40)

        amounts = re.findall(r'\$[\d,]+(?:\.\d{2})?', full_text)
        if amounts:
            try:
                max_amount = max(
                    float(a.replace('$', '').replace(',', '')) for a in amounts
                )
                if max_amount > 50000:
                    flags.append('LARGE_TRANSACTION_DETECTED')
                    findings.append(
                        f'Large transaction amount detected (${max_amount:,.2f}) — financial review required.'
                    )
                    risk_score = max(risk_score, 0.60)
            except ValueError:
                pass

        if not findings:
            findings.append('Billing document reviewed — no payment anomalies detected.')
            risk_score = max(risk_score, 0.10)

    # ── ID document ─────────────────────────────────────────────────────────
    if doc_type == 'id':
        flags.append('IDENTITY_DOCUMENT')
        findings.append('Identity document submitted — standard verification process applies.')
        risk_score = max(risk_score, 0.15)

    # ── Fallback for general docs ────────────────────────────────────────────
    if not findings:
        findings.append('General document analyzed — no specific risk indicators identified.')
        risk_score = max(risk_score, 0.10)

    # Determine risk level
    if risk_score >= 0.85:
        risk_level = 'very_high'
    elif risk_score >= 0.65:
        risk_level = 'high'
    elif risk_score >= 0.40:
        risk_level = 'medium'
    else:
        risk_level = 'low'

    # Determine recommendation
    if 'AUTHENTICITY_REQUIRES_INQUIRY' in flags or 'AUTHENTICITY_UNVERIFIABLE' in flags:
        recommendation = 'hold_pending_verification'
    elif 'DEATH_CERTIFICATE' in flags:
        recommendation = 'process_death_claim'
    elif 'DISABILITY_CERTIFICATE' in flags:
        recommendation = 'process_disability_claim'
    else:
        recommendation_map = {
            'very_high': 'decline_or_senior_review',
            'high': 'refer_manual_review',
            'medium': 'approve_conditional',
            'low': 'approve',
        }
        recommendation = recommendation_map.get(risk_level, 'approve')

    bi_insights = _generate_bi_insights(doc_type, entity_type, risk_level, flags)

    return {
        'risk_level': risk_level,
        'risk_score': round(risk_score, 3),
        'flags': flags,
        'findings': findings,
        'recommendation': recommendation,
        'bi_insights': bi_insights,
        'confidence': 0.85,
        'analyzed_at': datetime.now().isoformat(),
        'analysis_version': '1.0',
        'analysis_mode': 'rule_based_ai',
    }


def initialize_balance_sheet():
    """Initialize the PHINS balance sheet with default values if not already set"""
    global PHINS_BALANCE_SHEET
    if PHINS_BALANCE_SHEET.get('created_at') is None:
        PHINS_BALANCE_SHEET['created_at'] = datetime.now().isoformat()
        PHINS_BALANCE_SHEET['last_updated'] = datetime.now().isoformat()
        
        # Record initial capital deposit
        initial_deposit_tx = {
            'tx_id': f"BS-INIT-{datetime.now().strftime('%Y%m%d%H%M%S')}",
            'type': 'capital_deposit',
            'category': 'claims_reserve',
            'amount': 3500000.00,
            'description': 'Initial claims reserve capital - PHINS General Reserves Fund',
            'balance_after': 3500000.00,
            'actor': 'SYSTEM',
            'timestamp': datetime.now().isoformat()
        }
        PHINS_BALANCE_SHEET['transactions'].append(initial_deposit_tx)
        PHINS_BALANCE_SHEET['audit_log'].append({
            'action': 'initialize',
            'actor': 'SYSTEM',
            'timestamp': datetime.now().isoformat(),
            'details': 'Balance sheet initialized with $3,500,000 claims reserve'
        })
        print(f"✓ PHINS Balance Sheet initialized with $3,500,000 claims reserve")

def record_balance_sheet_transaction(
    tx_type: str,
    category: str,
    amount: float,
    description: str,
    actor: str = 'SYSTEM',
    metadata: Dict[str, Any] = None,
    customer_id: str = None,
    claim_id: str = None
) -> Dict[str, Any]:
    """
    Record a transaction on the PHINS main balance sheet.
    
    tx_type: 'revenue', 'expense', 'transfer', 'adjustment'
    category: 'claims_reserve', 'premium_income', 'claims_paid', etc.
    """
    global PHINS_BALANCE_SHEET
    
    tx_id = f"BS-{tx_type.upper()[:3]}-{datetime.now().strftime('%Y%m%d%H%M%S')}-{random.randint(1000, 9999)}"
    
    # Update the appropriate balance
    if tx_type == 'revenue':
        if category in PHINS_BALANCE_SHEET['revenue_breakdown']:
            PHINS_BALANCE_SHEET['revenue_breakdown'][category] += amount
        PHINS_BALANCE_SHEET['total_revenue'] += amount
        PHINS_BALANCE_SHEET['operating_reserve'] += amount
    elif tx_type == 'expense':
        if category in PHINS_BALANCE_SHEET['expense_breakdown']:
            PHINS_BALANCE_SHEET['expense_breakdown'][category] += amount
        PHINS_BALANCE_SHEET['total_expenses'] += amount
        
        # Deduct from appropriate reserve
        if category == 'claims_paid':
            PHINS_BALANCE_SHEET['claims_reserve'] -= amount
        elif category == 'supplier_payments':
            PHINS_BALANCE_SHEET['supplier_reserve'] -= amount
        else:
            PHINS_BALANCE_SHEET['operating_reserve'] -= amount
    elif tx_type == 'transfer':
        # Internal transfer between reserves - handled by caller
        pass
    elif tx_type == 'adjustment':
        # Manual adjustment - handled by caller
        pass
    
    # Calculate total balance
    total_balance = (
        PHINS_BALANCE_SHEET['claims_reserve'] +
        PHINS_BALANCE_SHEET['operating_reserve'] +
        PHINS_BALANCE_SHEET['supplier_reserve'] +
        PHINS_BALANCE_SHEET['investment_reserve']
    )
    
    transaction = {
        'tx_id': tx_id,
        'type': tx_type,
        'category': category,
        'amount': amount,
        'description': description,
        'customer_id': customer_id,
        'claim_id': claim_id,
        'metadata': metadata or {},
        'actor': actor,
        'balance_after': total_balance,
        'claims_reserve_after': PHINS_BALANCE_SHEET['claims_reserve'],
        'timestamp': datetime.now().isoformat()
    }
    
    PHINS_BALANCE_SHEET['transactions'].append(transaction)
    PHINS_BALANCE_SHEET['last_updated'] = datetime.now().isoformat()
    
    # Add audit entry
    PHINS_BALANCE_SHEET['audit_log'].append({
        'action': tx_type,
        'tx_id': tx_id,
        'actor': actor,
        'timestamp': datetime.now().isoformat(),
        'amount': amount,
        'category': category
    })
    
    # Also record on the main transaction ledger with PHINS owner
    nft_token = generate_nft_token(
        customer_id='PHINS-CORPORATE',
        transaction_type=f'balance_sheet_{tx_type}',
        transaction_id=tx_id,
        amount=amount if tx_type == 'revenue' else -amount,
        description=description,
        metadata={
            'balance_sheet_category': category,
            'customer_id': customer_id,
            'claim_id': claim_id,
            **(metadata or {})
        }
    )
    
    # Trigger save
    threading.Thread(target=save_ledger_data, daemon=True).start()
    
    return {**transaction, 'nft_token_id': nft_token['token_id']}

def process_claim_payment_to_wallet(
    claim_id: str,
    customer_id: str,
    amount: float,
    processed_by: str = 'accountant'
) -> Dict[str, Any]:
    """
    Process an approved claim payment by:
    1. Deducting from PHINS claims reserve
    2. Transferring directly to customer's health wallet
    3. Recording all transactions on ledger
    """
    global PHINS_BALANCE_SHEET, HEALTH_WALLETS
    
    # Check sufficient reserves
    if PHINS_BALANCE_SHEET['claims_reserve'] < amount:
        return {
            'success': False,
            'error': 'Insufficient claims reserve',
            'available': PHINS_BALANCE_SHEET['claims_reserve'],
            'required': amount
        }
    
    # Generate payment reference
    payment_ref = f"CLAIM-PAY-{datetime.now().strftime('%Y%m%d')}-{random.randint(10000, 99999)}"
    
    # 1. Record expense on balance sheet (deduct from claims reserve)
    bs_tx = record_balance_sheet_transaction(
        tx_type='expense',
        category='claims_paid',
        amount=amount,
        description=f"Claim payment {claim_id} to customer {customer_id}",
        actor=processed_by,
        customer_id=customer_id,
        claim_id=claim_id,
        metadata={
            'payment_reference': payment_ref,
            'destination': 'health_wallet'
        }
    )
    
    # 2. Ensure customer has health wallet
    if customer_id not in HEALTH_WALLETS:
        HEALTH_WALLETS[customer_id] = {
            'customer_id': customer_id,
            'balance': 0.00,
            'monthly_deposit': 0.00,
            'transactions': [],
            'created_at': datetime.now().isoformat()
        }
    
    # 3. Credit customer's health wallet
    prev_balance = HEALTH_WALLETS[customer_id]['balance']
    HEALTH_WALLETS[customer_id]['balance'] += amount
    new_balance = HEALTH_WALLETS[customer_id]['balance']
    
    # 4. Record wallet transaction
    wallet_tx = {
        'id': payment_ref,
        'type': 'claim_payment',
        'amount': amount,
        'source': 'PHINS_CLAIMS_RESERVE',
        'claim_id': claim_id,
        'description': f"Claim payment received - {claim_id}",
        'previous_balance': prev_balance,
        'balance_after': new_balance,
        'timestamp': datetime.now().isoformat()
    }
    HEALTH_WALLETS[customer_id]['transactions'].append(wallet_tx)
    
    # 5. Record on customer's transaction ledger
    customer_tx = record_transaction(
        customer_id=customer_id,
        tx_type='claim_payment_received',
        amount=amount,
        description=f"Claim {claim_id} payment deposited to Health Wallet",
        metadata={
            'claim_id': claim_id,
            'payment_reference': payment_ref,
            'source': 'PHINS_CLAIMS_RESERVE',
            'previous_balance': prev_balance,
            'new_balance': new_balance,
            'balance_sheet_tx_id': bs_tx['tx_id']
        }
    )
    
    wallet_tx['nft_token_id'] = customer_tx.get('nft_token_id')
    wallet_tx['ledger_tx_id'] = customer_tx.get('id')
    
    return {
        'success': True,
        'payment_reference': payment_ref,
        'amount_paid': amount,
        'customer_id': customer_id,
        'claim_id': claim_id,
        'destination': 'health_wallet',
        'new_wallet_balance': new_balance,
        'balance_sheet_tx': bs_tx,
        'customer_tx': customer_tx,
        'claims_reserve_remaining': PHINS_BALANCE_SHEET['claims_reserve']
    }

def record_premium_revenue(
    customer_id: str,
    policy_id: str,
    amount: float,
    description: str = None
) -> Dict[str, Any]:
    """Record premium payment as revenue on the balance sheet"""
    return record_balance_sheet_transaction(
        tx_type='revenue',
        category='premium_income',
        amount=amount,
        description=description or f"Premium payment for policy {policy_id}",
        actor='billing_system',
        customer_id=customer_id,
        metadata={'policy_id': policy_id}
    )

def record_fee_revenue(
    fee_type: str,
    amount: float,
    description: str,
    customer_id: str = None,
    actor: str = 'SYSTEM'
) -> Dict[str, Any]:
    """Record various fees as revenue"""
    category_map = {
        'management': 'management_fees',
        'underwriting': 'underwriting_fees',
        'late': 'late_fees',
        'other': 'other_income'
    }
    category = category_map.get(fee_type, 'other_income')
    
    return record_balance_sheet_transaction(
        tx_type='revenue',
        category=category,
        amount=amount,
        description=description,
        actor=actor,
        customer_id=customer_id
    )

# ========== DATA PERSISTENCE LAYER ==========
# Path for persistent storage file
LEDGER_PERSISTENCE_FILE = os.environ.get(
    'LEDGER_PERSISTENCE_FILE',
    os.path.join(tempfile.gettempdir(), 'phins_ledger_data.json'),
)
PERSISTENCE_ENABLED = os.environ.get('ENABLE_LEDGER_PERSISTENCE', 'true').lower() == 'true'

# Loaded persistence buffers (used before services are initialized).
# These must exist even when load_ledger_data() is never called (e.g. unit tests importing this module).
_loaded_algo_balances: Dict[str, Any] = {}
_loaded_trading_bots: Dict[str, Any] = {}
_persistence_lock = threading.Lock()

def save_ledger_data():
    """Save all ledger data to persistent storage"""
    if not PERSISTENCE_ENABLED:
        return
    
    try:
        with _persistence_lock:
            # Collect algo trading balances from services if available
            algo_balances = {}
            try:
                if 'unified_balance_service' in globals() and unified_balance_service:
                    algo_balances = dict(unified_balance_service.algo_trading_balances)
                elif 'portfolio_tracker_service' in globals() and portfolio_tracker_service:
                    algo_balances = dict(portfolio_tracker_service.algo_balances)
            except:
                pass
            
            # Collect trading bots data
            trading_bots = {}
            try:
                if 'algo_trading_service' in globals() and algo_trading_service:
                    trading_bots = {k: v.__dict__ if hasattr(v, '__dict__') else v 
                                   for k, v in algo_trading_service.bots.items()}
            except:
                pass
            
            data = {
                'saved_at': datetime.now().isoformat(),
                'version': '2.0',
                'health_wallets': HEALTH_WALLETS,
                'medical_purchases': MEDICAL_PURCHASES,
                'nft_ledger': NFT_LEDGER,
                'customer_allocations': CUSTOMER_ALLOCATIONS,
                'investment_accounts': INVESTMENT_ACCOUNTS,
                'transaction_ledger': TRANSACTION_LEDGER,
                'billing': BILLING,
                'policies': POLICIES,
                'customers': CUSTOMERS,
                'underwriting_applications': UNDERWRITING_APPLICATIONS,
                # v1.2 additions - algo trading data
                'algo_trading_balances': algo_balances,
                'trading_bots': trading_bots,
                # v1.3 additions - PHINS Main Balance Sheet
                'phins_balance_sheet': PHINS_BALANCE_SHEET,
                # v1.4 additions - Claims and Claim Files
                'claims': dict(CLAIMS),
                'claim_files': CLAIM_FILES,
                # v1.5 additions - Underwriting Files
                'underwriting_files': UNDERWRITING_FILES,
                # v1.6 additions - Media Assets and Design Settings
                'media_assets': MEDIA_ASSETS,
                'media_processing_jobs': MEDIA_PROCESSING_JOBS,
                'design_settings': DESIGN_SETTINGS,
                # v1.7 additions - Invitation Codes and Registered Customers
                'invitation_codes': INVITATION_CODES,
                'registered_customers': REGISTERED_CUSTOMERS,
                # v1.8 additions - Customer Referral System
                'customer_invitations': CUSTOMER_INVITATIONS,
                'customer_referral_stats': CUSTOMER_REFERRAL_STATS,
                # v1.9 additions - General Policy Documents
                'policy_documents': POLICY_DOCUMENTS
            }
            
            # Write to temp file first, then rename for atomic operation
            temp_file = LEDGER_PERSISTENCE_FILE + '.tmp'
            with open(temp_file, 'w') as f:
                json.dump(data, f, default=str, indent=2)
            
            # Atomic rename
            os.rename(temp_file, LEDGER_PERSISTENCE_FILE)
            print(f"[PERSISTENCE] Saved ledger data to {LEDGER_PERSISTENCE_FILE}")
            if algo_balances:
                print(f"  - Algo Trading Balances: {len(algo_balances)} accounts")
    except Exception as e:
        print(f"[PERSISTENCE] Error saving ledger data: {e}")

def append_customer_to_seeds(email: str, password: str, name: str, customer_id: str, registered_at: str):
    """
    Append newly registered customer to dynamic seeds file for restart persistence.
    
    SECURITY: Passwords are hashed before storage - NEVER store plain-text passwords.
    """
    try:
        seeds_file = os.path.join(os.path.dirname(__file__), '..', 'database', 'dynamic_customers.json')
        
        # Load existing dynamic customers
        dynamic_customers = []
        if os.path.exists(seeds_file):
            with open(seeds_file, 'r') as f:
                dynamic_customers = json.load(f)
        
        # SECURITY: Hash password before storing
        pwd_hash = hash_password(password)
        
        # Add new customer with hashed password
        dynamic_customers.append({
            'username': email,
            # SECURITY: Store hash and salt, NEVER plain-text password
            'password_hash': pwd_hash['hash'],
            'password_salt': pwd_hash['salt'],
            'name': name,
            'role': 'customer',
            'customer_id': customer_id,
            'email': email,
            'registered_at': registered_at
        })
        
        # Save back
        with open(seeds_file, 'w') as f:
            json.dump(dynamic_customers, f, indent=2)
        
        print(f"[SEEDS] Appended new customer {email} to dynamic seeds file (password hashed)")
    except Exception as e:
        print(f"[SEEDS] Error appending customer to seeds: {e}")

# ========== PERSISTENT INVITATION CODES STORAGE ==========
# Store invitation codes in a git-tracked JSON file so they persist across Railway deployments
INVITATION_CODES_FILE = os.path.join(os.path.dirname(__file__), '..', 'database', 'invitation_codes.json')

def save_invitation_codes_to_file():
    """
    Save all invitation codes (admin + customer) to persistent JSON file.
    This file is git-tracked and persists across Railway deployments.
    """
    global INVITATION_CODES, CUSTOMER_INVITATIONS, CUSTOMER_REFERRAL_STATS
    
    try:
        data = {
            'version': '1.0',
            'saved_at': datetime.now().isoformat(),
            'admin_codes': dict(INVITATION_CODES),
            'customer_codes': dict(CUSTOMER_INVITATIONS),
            'referral_stats': dict(CUSTOMER_REFERRAL_STATS)
        }
        
        with open(INVITATION_CODES_FILE, 'w') as f:
            json.dump(data, f, indent=2, default=str)
        
        print(f"[INVITATIONS] Saved {len(INVITATION_CODES)} admin codes, {len(CUSTOMER_INVITATIONS)} customer codes to persistent file")
    except Exception as e:
        print(f"[INVITATIONS] Error saving invitation codes: {e}")

def load_invitation_codes_from_file():
    """
    Load invitation codes from persistent JSON file on startup.
    """
    global INVITATION_CODES, CUSTOMER_INVITATIONS, CUSTOMER_REFERRAL_STATS
    
    try:
        if not os.path.exists(INVITATION_CODES_FILE):
            print("[INVITATIONS] No invitation codes file found, starting fresh")
            return 0
        
        with open(INVITATION_CODES_FILE, 'r') as f:
            data = json.load(f)
        
        # Load admin codes
        admin_codes = data.get('admin_codes', {})
        if admin_codes:
            INVITATION_CODES.update(admin_codes)
            print(f"[INVITATIONS] Loaded {len(admin_codes)} admin invitation codes")
        
        # Load customer codes
        customer_codes = data.get('customer_codes', {})
        if customer_codes:
            CUSTOMER_INVITATIONS.update(customer_codes)
            print(f"[INVITATIONS] Loaded {len(customer_codes)} customer referral codes")
        
        # Load referral stats
        referral_stats = data.get('referral_stats', {})
        if referral_stats:
            CUSTOMER_REFERRAL_STATS.update(referral_stats)
            print(f"[INVITATIONS] Loaded referral stats for {len(referral_stats)} customers")
        
        return len(admin_codes) + len(customer_codes)
        
    except json.JSONDecodeError as e:
        print(f"[INVITATIONS] Error parsing invitation codes file: {e}")
        return 0
    except Exception as e:
        print(f"[INVITATIONS] Error loading invitation codes: {e}")
        return 0

def load_dynamic_customers():
    """
    Load dynamically registered customers from JSON file into USERS dictionary.
    
    SECURITY: Supports both pre-hashed passwords (new secure format) and 
    legacy plain-text passwords (for backward compatibility during migration).
    """
    global USERS, CUSTOMERS, REGISTERED_CUSTOMERS
    
    seeds_file = os.path.join(os.path.dirname(__file__), '..', 'database', 'dynamic_customers.json')
    
    try:
        if not os.path.exists(seeds_file):
            print("[DYNAMIC] No dynamic customers file found")
            return 0
        
        with open(seeds_file, 'r') as f:
            dynamic_customers = json.load(f)
        
        if not dynamic_customers:
            print("[DYNAMIC] Dynamic customers file is empty")
            return 0
        
        loaded_count = 0
        legacy_count = 0
        
        for customer in dynamic_customers:
            email = customer.get('email') or customer.get('username')
            if not email:
                continue
            
            # Skip if already exists
            if email in USERS:
                continue
            
            # SECURITY: Check if password is already hashed (new secure format)
            if 'password_hash' in customer and 'password_salt' in customer:
                # New format: pre-hashed password
                pwd_hash = customer['password_hash']
                pwd_salt = customer['password_salt']
            elif 'password' in customer:
                # LEGACY: Plain-text password (migrate and hash)
                # SECURITY: Default password from env var, or generate random unusable password
                default_pwd = os.environ.get('PHINS_DEFAULT_CUSTOMER_PASSWORD', secrets.token_urlsafe(32))
                pwd_data = hash_password(customer.get('password', default_pwd))
                pwd_hash = pwd_data['hash']
                pwd_salt = pwd_data['salt']
                legacy_count += 1
            else:
                # No password at all - generate unusable random password
                pwd_data = hash_password(secrets.token_urlsafe(32))
                pwd_hash = pwd_data['hash']
                pwd_salt = pwd_data['salt']
            
            USERS[email] = {
                'hash': pwd_hash,
                'salt': pwd_salt,
                'role': 'customer',
                'name': customer.get('name', email),
                'customer_id': customer.get('customer_id', f"CUST-{email}")
            }
            
            # Also add to CUSTOMERS if customer_id is present
            customer_id = customer.get('customer_id')
            if customer_id and customer_id not in CUSTOMERS:
                CUSTOMERS[customer_id] = {
                    'id': customer_id,
                    'name': customer.get('name', email),
                    'email': email,
                    'phone': customer.get('phone', ''),
                    'registered_at': customer.get('registered_at', datetime.now().isoformat()),
                    'created_date': customer.get('registered_at', datetime.now().isoformat())
                }
                REGISTERED_CUSTOMERS[customer_id] = CUSTOMERS[customer_id]
            
            loaded_count += 1
        
        if legacy_count > 0:
            print(f"[DYNAMIC] WARNING: {legacy_count} customers have legacy plain-text passwords. Run password migration.")
        
        print(f"[DYNAMIC] Loaded {loaded_count} dynamic customers from seeds file")
        return loaded_count
        
    except json.JSONDecodeError as e:
        print(f"[DYNAMIC] Error parsing dynamic customers file: {e}")
        return 0
    except Exception as e:
        print(f"[DYNAMIC] Error loading dynamic customers: {e}")
        return 0

def load_ledger_data():
    """Load ledger data from persistent storage on startup"""
    global HEALTH_WALLETS, MEDICAL_PURCHASES, NFT_LEDGER, CUSTOMER_ALLOCATIONS, INVESTMENT_ACCOUNTS, TRANSACTION_LEDGER
    global BILLING, POLICIES, CUSTOMERS, UNDERWRITING_APPLICATIONS, PHINS_BALANCE_SHEET, CLAIMS, CLAIM_FILES, UNDERWRITING_FILES
    global MEDIA_ASSETS, DESIGN_SETTINGS, INVITATION_CODES, REGISTERED_CUSTOMERS
    global CUSTOMER_INVITATIONS, CUSTOMER_REFERRAL_STATS
    global POLICY_DOCUMENTS
    global _loaded_algo_balances, _loaded_trading_bots
    
    # Temporary storage for algo data until services are initialized
    _loaded_algo_balances = {}
    _loaded_trading_bots = {}
    
    if not PERSISTENCE_ENABLED:
        print("[PERSISTENCE] Persistence disabled, using in-memory storage only")
        return False
    
    if not os.path.exists(LEDGER_PERSISTENCE_FILE):
        print(f"[PERSISTENCE] No persistence file found at {LEDGER_PERSISTENCE_FILE}, starting fresh")
        return False
    
    try:
        with open(LEDGER_PERSISTENCE_FILE, 'r') as f:
            data = json.load(f)
        
        # Load each data store
        HEALTH_WALLETS.update(data.get('health_wallets', {}))
        MEDICAL_PURCHASES.update(data.get('medical_purchases', {}))
        NFT_LEDGER.update(data.get('nft_ledger', {}))
        CUSTOMER_ALLOCATIONS.update(data.get('customer_allocations', {}))
        INVESTMENT_ACCOUNTS.update(data.get('investment_accounts', {}))
        TRANSACTION_LEDGER.update(data.get('transaction_ledger', {}))
        platform_event_ledger.ensure_hash_chain()
        
        # Load pipeline data (v1.1+)
        if data.get('version', '1.0') >= '1.1':
            BILLING.update(data.get('billing', {}))
            POLICIES.update(data.get('policies', {}))
            CUSTOMERS.update(data.get('customers', {}))
            UNDERWRITING_APPLICATIONS.update(data.get('underwriting_applications', {}))
        
        # Load algo trading data (v1.2+)
        if data.get('version', '1.0') >= '1.2':
            _loaded_algo_balances = data.get('algo_trading_balances', {})
            _loaded_trading_bots = data.get('trading_bots', {})
        
        # Load PHINS Balance Sheet (v1.3+)
        if data.get('version', '1.0') >= '1.3':
            loaded_bs = data.get('phins_balance_sheet', {})
            if loaded_bs:
                PHINS_BALANCE_SHEET.update(loaded_bs)
                print(f"  - PHINS Balance Sheet: Claims Reserve ${PHINS_BALANCE_SHEET.get('claims_reserve', 0):,.2f}")
        
        # Load Claims and Claim Files (v1.4+)
        if data.get('version', '1.0') >= '1.4':
            loaded_claims = data.get('claims', {})
            loaded_claim_files = data.get('claim_files', {})
            if loaded_claims:
                CLAIMS.update(loaded_claims)
                print(f"  - Claims: {len(CLAIMS)} claims loaded from persistence")
            if loaded_claim_files:
                CLAIM_FILES.update(loaded_claim_files)
                print(f"  - Claim Files: {len(CLAIM_FILES)} files loaded from persistence")
        
        # Load Underwriting Files (v1.5+)
        if data.get('version', '1.0') >= '1.5':
            loaded_uw_files = data.get('underwriting_files', {})
            if loaded_uw_files:
                UNDERWRITING_FILES.update(loaded_uw_files)
                print(f"  - Underwriting Files: {len(UNDERWRITING_FILES)} files loaded from persistence")
        
        # Load Media Assets and Design Settings (v1.6+)
        if data.get('version', '1.0') >= '1.6':
            loaded_media = data.get('media_assets', {})
            loaded_media_jobs = data.get('media_processing_jobs', {})
            loaded_design = data.get('design_settings', {})
            if loaded_media:
                MEDIA_ASSETS.update(loaded_media)
                print(f"  - Media Assets: {len(MEDIA_ASSETS)} assets loaded from persistence")
            if loaded_media_jobs:
                MEDIA_PROCESSING_JOBS.update(loaded_media_jobs)
                print(f"  - Media Processing Jobs: {len(MEDIA_PROCESSING_JOBS)} jobs loaded from persistence")
            if loaded_design:
                DESIGN_SETTINGS.update(loaded_design)
                print(f"  - Design Settings: Loaded (video: {'✓' if DESIGN_SETTINGS.get('hero_video_id') or DESIGN_SETTINGS.get('video_url') else '✗'})")
        
        # Load Invitation Codes and Registered Customers (v1.7+)
        if data.get('version', '1.0') >= '1.7':
            loaded_invitations = data.get('invitation_codes', {})
            loaded_registered = data.get('registered_customers', {})
            if loaded_invitations:
                INVITATION_CODES.update(loaded_invitations)
                print(f"  - Invitation Codes: {len(INVITATION_CODES)} codes loaded from persistence")
            if loaded_registered:
                REGISTERED_CUSTOMERS.update(loaded_registered)
                # Also restore to CUSTOMERS if not already there
                for cust_id, cust_data in loaded_registered.items():
                    if cust_id not in CUSTOMERS:
                        CUSTOMERS[cust_id] = cust_data
                print(f"  - Registered Customers: {len(REGISTERED_CUSTOMERS)} customers loaded from persistence")
        
        # Load Customer Invitations and Referral Stats (v1.8+)
        loaded_customer_invitations = data.get('customer_invitations', {})
        loaded_referral_stats = data.get('customer_referral_stats', {})
        if loaded_customer_invitations:
            CUSTOMER_INVITATIONS.update(loaded_customer_invitations)
            print(f"  - Customer Invitations: {len(CUSTOMER_INVITATIONS)} referral codes loaded from persistence")
        if loaded_referral_stats:
            CUSTOMER_REFERRAL_STATS.update(loaded_referral_stats)
            print(f"  - Customer Referral Stats: {len(CUSTOMER_REFERRAL_STATS)} customer stats loaded from persistence")
        
        # Load Policy Documents (v1.9+)
        loaded_policy_docs = data.get('policy_documents', {})
        if loaded_policy_docs:
            POLICY_DOCUMENTS.update(loaded_policy_docs)
            print(f"  - Policy Documents: {len(POLICY_DOCUMENTS)} documents loaded from persistence")
            hydrated = hydrate_document_customer_links()
            if hydrated:
                print(f"  - Policy Documents: hydrated owner links for {hydrated} legacy document(s)")
        
        print(f"[PERSISTENCE] Loaded ledger data from {LEDGER_PERSISTENCE_FILE}")
        print(f"  - Health Wallets: {len(HEALTH_WALLETS)}")
        print(f"  - Medical Purchases: {len(MEDICAL_PURCHASES)}")
        print(f"  - NFT Ledger: {len(NFT_LEDGER)}")
        print(f"  - Customer Allocations: {len(CUSTOMER_ALLOCATIONS)}")
        print(f"  - Investment Accounts: {len(INVESTMENT_ACCOUNTS)}")
        print(f"  - Transaction Ledger: {len(TRANSACTION_LEDGER)}")
        print(f"  - Billing: {len(BILLING)}")
        print(f"  - Policies: {len(POLICIES)}")
        print(f"  - Customers: {len(CUSTOMERS)}")
        print(f"  - Underwriting: {len(UNDERWRITING_APPLICATIONS)}")
        if _loaded_algo_balances:
            print(f"  - Algo Trading Balances: {len(_loaded_algo_balances)} accounts (pending sync)")
        if _loaded_trading_bots:
            print(f"  - Trading Bots: {len(_loaded_trading_bots)} bots (pending sync)")
        print(f"  - Saved at: {data.get('saved_at', 'unknown')}")
        return True
    except Exception as e:
        print(f"[PERSISTENCE] Error loading ledger data: {e}")
        return False

def sync_loaded_algo_data():
    """Sync loaded algo trading data to services after they're initialized"""
    global _loaded_algo_balances, _loaded_trading_bots
    
    try:
        if _loaded_algo_balances:
            if 'unified_balance_service' in globals() and unified_balance_service:
                unified_balance_service.algo_trading_balances.update(_loaded_algo_balances)
                print(f"[PERSISTENCE] Synced {len(_loaded_algo_balances)} algo balances to unified_balance_service")
            if 'portfolio_tracker_service' in globals() and portfolio_tracker_service:
                portfolio_tracker_service.algo_balances.update(_loaded_algo_balances)
                print(f"[PERSISTENCE] Synced {len(_loaded_algo_balances)} algo balances to portfolio_tracker_service")
            _loaded_algo_balances = {}
        
        # Note: Trading bots would need more complex reconstruction
        # For now, just log that they were available
        if _loaded_trading_bots:
            print(f"[PERSISTENCE] {len(_loaded_trading_bots)} trading bots available for restoration")
            _loaded_trading_bots = {}
    except Exception as e:
        print(f"[PERSISTENCE] Error syncing algo data: {e}")

def schedule_periodic_save():
    """Schedule periodic saves of ledger data"""
    def save_loop():
        while True:
            time.sleep(60)  # Save every 60 seconds
            save_ledger_data()
    
    if PERSISTENCE_ENABLED:
        save_thread = threading.Thread(target=save_loop, daemon=True)
        save_thread.start()
        print("[PERSISTENCE] Started periodic save thread (every 60 seconds)")

