        # Aggregated platform-wide data for admin dashboard predictions & statistics
        if path == '/api/admin/platform-analytics':
            # Aggregate all customer data for platform-wide insights
            
            # 1. Platform Totals
            total_customers = len(CUSTOMERS)
            total_deposits = sum(
                sum(tx.get('amount', 0) for tx in w.get('transactions', []) if tx.get('type') == 'deposit')
                for w in HEALTH_WALLETS.values()
            )
            total_medical_purchases = sum(p.get('amount', 0) for p in MEDICAL_PURCHASES.values())
            total_investment_volume = sum(
                sum(d.get('amount', 0) for d in acc.get('deposits', []))
                for acc in INVESTMENT_ACCOUNTS.values()
            )
            
            # Algo trading volume from transaction ledger
            total_algo_volume = sum(
                abs(tx.get('amount', 0)) 
                for tx in TRANSACTION_LEDGER.values() 
                if tx.get('tx_type') in ['algo_trade', 'algo_order']
            )
            
            # 2. Medical Purchases by Category
            medical_by_category = {}
            for purchase in MEDICAL_PURCHASES.values():
                cat = purchase.get('category', 'general')
                if cat not in medical_by_category:
                    medical_by_category[cat] = {'count': 0, 'total': 0, 'products': {}}
                medical_by_category[cat]['count'] += 1
                medical_by_category[cat]['total'] += purchase.get('amount', 0)
                
                # Track individual products
                product = purchase.get('product_name', 'Unknown')
                if product not in medical_by_category[cat]['products']:
                    medical_by_category[cat]['products'][product] = {'count': 0, 'total': 0}
                medical_by_category[cat]['products'][product]['count'] += 1
                medical_by_category[cat]['products'][product]['total'] += purchase.get('amount', 0)
            
            # 3. Investments by Asset Type
            investments_by_asset = {
                'index_funds': {'customers': 0, 'total_usd': 0},
                'bonds': {'customers': 0, 'total_usd': 0},
                'crypto': {'customers': 0, 'total_usd': 0},
                'algo_trading': {'customers': 0, 'total_usd': 0}
            }
            for cust_id, acc in INVESTMENT_ACCOUNTS.items():
                if acc.get('index_balance', 0) > 0:
                    investments_by_asset['index_funds']['customers'] += 1
                    investments_by_asset['index_funds']['total_usd'] += acc.get('index_balance', 0)
                if acc.get('bonds_balance', 0) > 0:
                    investments_by_asset['bonds']['customers'] += 1
                    investments_by_asset['bonds']['total_usd'] += acc.get('bonds_balance', 0)
                if acc.get('crypto_balance', 0) > 0:
                    investments_by_asset['crypto']['customers'] += 1
                    investments_by_asset['crypto']['total_usd'] += acc.get('crypto_balance', 0)
            
            # Algo trading customer count
            algo_customers = set()
            for tx in TRANSACTION_LEDGER.values():
                if tx.get('tx_type') in ['algo_trade', 'algo_order']:
                    algo_customers.add(tx.get('customer_id'))
            investments_by_asset['algo_trading']['customers'] = len(algo_customers)
            investments_by_asset['algo_trading']['total_usd'] = total_algo_volume
            
            # 4. Algo Trading Stats
            algo_orders = [tx for tx in TRANSACTION_LEDGER.values() if tx.get('tx_type') in ['algo_trade', 'algo_order']]
            algo_stats = {
                'active_bots': len(getattr(algo_trading_service, 'bots', {})) if algo_trading_enabled else 0,
                'total_orders': len(algo_orders),
                'total_volume': total_algo_volume,
                'unique_customers': len(algo_customers),
                'avg_order_size': total_algo_volume / len(algo_orders) if algo_orders else 0
            }
            
            # 5. Ledger Integrity
            nft_count = len(NFT_LEDGER)
            tx_count = len(TRANSACTION_LEDGER)
            ledger_integrity = {
                'nft_tokens': nft_count,
                'transaction_records': tx_count,
                'integrity_score': 100 if nft_count > 0 and tx_count > 0 else 0,
                'medical_nfts': len([n for n in NFT_LEDGER.values() if n.get('transaction_type') == 'medical_purchase']),
                'deposit_nfts': len([n for n in NFT_LEDGER.values() if n.get('transaction_type') == 'wallet_deposit']),
                'investment_nfts': len([n for n in NFT_LEDGER.values() if n.get('transaction_type') == 'investment_deposit']),
                'algo_nfts': len([n for n in NFT_LEDGER.values() if n.get('transaction_type') in ['algo_trade', 'algo_order']])
            }
            
            # 6. Transaction Breakdown by Type
            tx_by_type = {}
            for tx in TRANSACTION_LEDGER.values():
                tx_type = tx.get('tx_type', 'unknown')
                if tx_type not in tx_by_type:
                    tx_by_type[tx_type] = {'count': 0, 'total_amount': 0}
                tx_by_type[tx_type]['count'] += 1
                tx_by_type[tx_type]['total_amount'] += abs(tx.get('amount', 0))
            
            # 7. Health Wallet Summary
            wallet_summary = {
                'total_wallets': len(HEALTH_WALLETS),
                'total_balance': sum(w.get('balance', 0) for w in HEALTH_WALLETS.values()),
                'total_deposits': total_deposits,
                'total_spent': total_medical_purchases,
                'avg_balance': sum(w.get('balance', 0) for w in HEALTH_WALLETS.values()) / len(HEALTH_WALLETS) if HEALTH_WALLETS else 0
            }
            
            # 8. Predictions / BI Metrics
            avg_purchase_per_customer = total_medical_purchases / total_customers if total_customers > 0 else 0
            avg_investment_per_customer = total_investment_volume / total_customers if total_customers > 0 else 0
            
            predictions = {
                'avg_purchase_per_customer': avg_purchase_per_customer,
                'avg_investment_per_customer': avg_investment_per_customer,
                'projected_monthly_purchases': total_medical_purchases * 1.1,  # 10% growth
                'projected_monthly_investments': total_investment_volume * 1.15,  # 15% growth
                'customer_lifetime_value': (avg_purchase_per_customer + avg_investment_per_customer) * 12,
                'platform_health_score': min(100, (nft_count + tx_count) / max(1, total_customers) * 10)
            }
            
            # 9. Top Products
            all_products = {}
            for purchase in MEDICAL_PURCHASES.values():
                product = purchase.get('product_name', 'Unknown')
                if product not in all_products:
                    all_products[product] = {'count': 0, 'total': 0}
                all_products[product]['count'] += 1
                all_products[product]['total'] += purchase.get('amount', 0)
            
            top_products = sorted(all_products.items(), key=lambda x: x[1]['count'], reverse=True)[:10]
            
            self._set_json_headers()
            self.wfile.write(json.dumps({
                'success': True,
                'platform_totals': {
                    'total_customers': total_customers,
                    'total_deposits': total_deposits,
                    'total_medical_purchases': total_medical_purchases,
                    'total_investment_volume': total_investment_volume,
                    'total_algo_trading_volume': total_algo_volume,
                    'total_aum': total_deposits + total_investment_volume + total_algo_volume
                },
                'medical_by_category': medical_by_category,
                'investments_by_asset': investments_by_asset,
                'algo_trading': algo_stats,
                'ledger_integrity': ledger_integrity,
                'transactions_by_type': tx_by_type,
                'wallet_summary': wallet_summary,
                'predictions': predictions,
                'top_products': [{'name': p[0], **p[1]} for p in top_products],
                'timestamp': datetime.now().isoformat()
            }, default=str).encode('utf-8'))
            return
        
        # ========== END PLATFORM ANALYTICS API ==========
        
        # ========== PHINS BALANCE SHEET API (ADMIN) ==========
        # Company balance sheet for claims reserves, revenue, and expenses
        # Accessible by: admin, accountant, underwriter, claims_adjuster
        
        if path == '/api/admin/balance-sheet':
            # Check authorization
            if not require_role(session, ['admin', 'accountant', 'underwriter', 'claims']):
                self._set_json_headers(403)
                self.wfile.write(json.dumps({'error': 'Unauthorized. Admin, Accountant, Underwriter, or Claims Adjuster access required.'}).encode('utf-8'))
                return
            
            # Initialize balance sheet if needed
            initialize_balance_sheet()
            
            # Calculate totals
            total_balance = (
                PHINS_BALANCE_SHEET['claims_reserve'] +
                PHINS_BALANCE_SHEET['operating_reserve'] +
                PHINS_BALANCE_SHEET['supplier_reserve'] +
                PHINS_BALANCE_SHEET['investment_reserve']
            )
            
            cumulative_premium_data = calculate_cumulative_premium_income(exclude_suspended=True)

            # Inject cumulative premium into balance sheet so revenue_breakdown reflects actuals
            PHINS_BALANCE_SHEET['revenue_breakdown']['premium_income'] = cumulative_premium_data['total']
            PHINS_BALANCE_SHEET['total_revenue'] = round(sum(PHINS_BALANCE_SHEET['revenue_breakdown'].values()), 2)

            self._set_json_headers()
            self.wfile.write(json.dumps({
                'success': True,
                'balance_sheet': {
                    'account_id': PHINS_BALANCE_SHEET['account_id'],
                    'name': PHINS_BALANCE_SHEET['name'],
                    'created_at': PHINS_BALANCE_SHEET['created_at'],
                    'last_updated': PHINS_BALANCE_SHEET['last_updated'],
                    
                    # Balances
                    'total_balance': total_balance,
                    'claims_reserve': PHINS_BALANCE_SHEET['claims_reserve'],
                    'operating_reserve': PHINS_BALANCE_SHEET['operating_reserve'],
                    'supplier_reserve': PHINS_BALANCE_SHEET['supplier_reserve'],
                    'investment_reserve': PHINS_BALANCE_SHEET['investment_reserve'],
                    
                    # Revenue
                    'total_revenue': PHINS_BALANCE_SHEET['total_revenue'],
                    'revenue_breakdown': PHINS_BALANCE_SHEET['revenue_breakdown'],
                    
                    # Cumulative premium (actuals from billing + ledger)
                    'cumulative_premium': cumulative_premium_data['total'],
                    'cumulative_premium_breakdown': {
                        'from_bills': cumulative_premium_data['from_bills'],
                        'from_ledger': cumulative_premium_data['ledger_unbilled_total'],
                    },
                    
                    # Expenses
                    'total_expenses': PHINS_BALANCE_SHEET['total_expenses'],
                    'expense_breakdown': PHINS_BALANCE_SHEET['expense_breakdown'],
                    
                    # Net position
                    'net_income': PHINS_BALANCE_SHEET['total_revenue'] - PHINS_BALANCE_SHEET['total_expenses'],
                    
                    # Transaction count
                    'transaction_count': len(PHINS_BALANCE_SHEET['transactions'])
                },
                'timestamp': datetime.now().isoformat()
            }, default=str).encode('utf-8'))
            return
        
        if path == '/api/admin/balance-sheet/transactions':
            # Check authorization
            if not require_role(session, ['admin', 'accountant', 'underwriter', 'claims']):
                self._set_json_headers(403)
                self.wfile.write(json.dumps({'error': 'Unauthorized.'}).encode('utf-8'))
                return
            
            # Get pagination params
            limit = int(qs.get('limit', [50])[0])
            offset = int(qs.get('offset', [0])[0])
            tx_type = qs.get('type', [None])[0]
            
            # Filter and sort transactions (most recent first)
            transactions = PHINS_BALANCE_SHEET.get('transactions', [])
            if tx_type:
                transactions = [tx for tx in transactions if tx.get('type') == tx_type]
            
            transactions = sorted(transactions, key=lambda x: x.get('timestamp', ''), reverse=True)
            paginated = transactions[offset:offset + limit]
            
            self._set_json_headers()
            self.wfile.write(json.dumps({
                'success': True,
                'transactions': paginated,
                'total': len(transactions),
                'limit': limit,
                'offset': offset,
                'timestamp': datetime.now().isoformat()
            }, default=str).encode('utf-8'))
            return
        
        if path == '/api/admin/balance-sheet/audit-log':
            # Check authorization - only admin and accountant
            if not require_role(session, ['admin', 'accountant']):
                self._set_json_headers(403)
                self.wfile.write(json.dumps({'error': 'Unauthorized. Admin or Accountant access required.'}).encode('utf-8'))
                return
            
            # Get pagination params
            limit = int(qs.get('limit', [100])[0])
            offset = int(qs.get('offset', [0])[0])
            
            audit_log = PHINS_BALANCE_SHEET.get('audit_log', [])
            audit_log = sorted(audit_log, key=lambda x: x.get('timestamp', ''), reverse=True)
            paginated = audit_log[offset:offset + limit]
            
            self._set_json_headers()
            self.wfile.write(json.dumps({
                'success': True,
                'audit_log': paginated,
                'total': len(audit_log),
                'limit': limit,
                'offset': offset,
                'timestamp': datetime.now().isoformat()
            }, default=str).encode('utf-8'))
            return
        
        if path == '/api/admin/balance-sheet/summary':
            # Quick summary for dashboard widgets - slightly less restricted
            if not require_role(session, ['admin', 'accountant', 'underwriter', 'claims']):
                self._set_json_headers(403)
                self.wfile.write(json.dumps({'error': 'Unauthorized.'}).encode('utf-8'))
                return
            
            initialize_balance_sheet()
            
            # Recent claims paid
            recent_claims = [
                tx for tx in PHINS_BALANCE_SHEET.get('transactions', [])
                if tx.get('category') == 'claims_paid'
            ][-10:]
            
            self._set_json_headers()
            self.wfile.write(json.dumps({
                'success': True,
                'summary': {
                    'claims_reserve': PHINS_BALANCE_SHEET['claims_reserve'],
                    'total_claims_paid': PHINS_BALANCE_SHEET['expense_breakdown']['claims_paid'],
                    'total_premium_income': PHINS_BALANCE_SHEET['revenue_breakdown']['premium_income'],
                    'net_position': PHINS_BALANCE_SHEET['total_revenue'] - PHINS_BALANCE_SHEET['total_expenses'],
                    'recent_claims_count': len(recent_claims),
                    'last_updated': PHINS_BALANCE_SHEET['last_updated']
                },
                'recent_claims': recent_claims,
                'timestamp': datetime.now().isoformat()
            }, default=str).encode('utf-8'))
            return
        
        # AI/BI Financial Intelligence Endpoint - Comprehensive analysis
        if path == '/api/admin/balance-sheet/ai-insights':
            if not require_role(session, ['admin', 'accountant', 'actuary']):
                self._set_json_headers(403)
                self.wfile.write(json.dumps({'error': 'Unauthorized. Admin/Accountant/Actuary access required.'}).encode('utf-8'))
                return
            
            initialize_balance_sheet()
            
            # ========== AI/BI FINANCIAL ANALYSIS ==========
            
            # 1. Calculate key financial metrics
            claims_reserve = PHINS_BALANCE_SHEET['claims_reserve']
            premium_income = PHINS_BALANCE_SHEET['revenue_breakdown']['premium_income']
            claims_paid = PHINS_BALANCE_SHEET['expense_breakdown']['claims_paid']
            total_revenue = PHINS_BALANCE_SHEET['total_revenue']
            total_expenses = PHINS_BALANCE_SHEET['total_expenses']
            net_income = total_revenue - total_expenses
            
            # 2. Get policy and billing data for projections
            active_policies = [p for p in POLICIES.values() if status_eq(p, 'active')]
            all_policies = list(POLICIES.values())
            total_annual_premium_potential = sum(float(p.get('annual_premium', 0)) for p in active_policies)
            total_monthly_premium_potential = sum(float(p.get('monthly_premium', 0)) for p in active_policies)
            
            # Outstanding bills analysis
            outstanding_bills = [b for b in BILLING.values() if status_in(b, ['outstanding', 'pending'])]
            total_outstanding = sum(float(b.get('amount', 0) - b.get('amount_paid', 0)) for b in outstanding_bills)
            
            # Claims analysis
            paid_claims = [c for c in CLAIMS.values() if status_eq(c, 'paid')]
            pending_claims = [c for c in CLAIMS.values() if status_in(c, ['pending', 'under_review'])]
            total_pending_claims_value = sum(float(c.get('claimed_amount', 0)) for c in pending_claims)
            
            # 3. Calculate financial ratios
            loss_ratio = (claims_paid / premium_income * 100) if premium_income > 0 else float('inf') if claims_paid > 0 else 0
            reserve_coverage_months = (claims_reserve / (claims_paid / max(1, len(paid_claims)))) if claims_paid > 0 else float('inf')
            collection_rate = (premium_income / total_annual_premium_potential * 100) if total_annual_premium_potential > 0 else 0
            
            # 4. AI-Generated Insights and Recommendations
            insights = []
            recommendations = []
            risk_alerts = []
            
            # ========== BILLING VALIDATION CHECKS ==========
            # Check for billing discrepancies and validation issues
            
            billing_validation = {
                'unbilled_customers': [],
                'duplicate_bills': [],
                'bills_not_on_balance_sheet': [],
                'overbilled_customers': [],
                'missing_premium_policies': []
            }
            
            # 4a. Find customers with active policies but no billing records
            for policy in active_policies:
                policy_id = policy.get('id') or policy.get('policy_id')
                customer_id = policy.get('customer_id')
                
                # Skip suspended accounts
                if is_suspended_account(customer_id):
                    continue
                
                # Check if this policy has any bills
                policy_bills = [b for b in BILLING.values() if b.get('policy_id') == policy_id]
                
                if len(policy_bills) == 0:
                    monthly_premium = float(policy.get('monthly_premium', 0) or 0)
                    annual_premium = float(policy.get('annual_premium', 0) or 0)
                    if monthly_premium > 0 or annual_premium > 0:
                        billing_validation['unbilled_customers'].append({
                            'customer_id': customer_id,
                            'policy_id': policy_id,
                            'monthly_premium': monthly_premium,
                            'annual_premium': annual_premium,
                            'issue': 'Active policy with no billing records'
                        })
                    else:
                        billing_validation['missing_premium_policies'].append({
                            'customer_id': customer_id,
                            'policy_id': policy_id,
                            'issue': 'Active policy with no premium amount set'
                        })
            
            # 4b. Check for duplicate bills (same customer+policy billed multiple times in same month)
            from collections import defaultdict
            billing_by_customer_policy_month = defaultdict(list)
            for bill_id, bill in BILLING.items():
                customer_id = bill.get('customer_id')
                policy_id = bill.get('policy_id')
                created_date = bill.get('created_date', '')
                billing_period = bill.get('billing_period', '')
                
                # Skip suspended accounts
                if is_suspended_account(customer_id):
                    continue
                
                # Get billing month from period or created date
                if billing_period:
                    month_key = billing_period[:7] if len(billing_period) >= 7 else billing_period
                elif created_date:
                    month_key = created_date[:7] if len(created_date) >= 7 else created_date
                else:
                    month_key = 'unknown'
                
                key = f"{customer_id}:{policy_id}:{month_key}"
                billing_by_customer_policy_month[key].append({
                    'bill_id': bill_id,
                    'amount': float(bill.get('amount', bill.get('amount_due', 0))),
                    'status': bill.get('status', ''),
                    'created_date': created_date
                })
            
            for key, bills in billing_by_customer_policy_month.items():
                if len(bills) > 1:
                    parts = key.split(':')
                    billing_validation['duplicate_bills'].append({
                        'customer_id': parts[0] if len(parts) > 0 else '',
                        'policy_id': parts[1] if len(parts) > 1 else '',
                        'billing_period': parts[2] if len(parts) > 2 else '',
                        'bills': bills,
                        'total_billed': sum(b['amount'] for b in bills),
                        'issue': f'Customer billed {len(bills)} times for same period'
                    })
            
            # 4c. Check if cumulative paid premiums are reflected in balance sheet
            premium_income_totals = calculate_cumulative_premium_income(exclude_suspended=True)
            total_paid_from_bills = premium_income_totals['total']
            
            if abs(total_paid_from_bills - premium_income) > 1.0:  # Allow $1 tolerance
                billing_validation['bills_not_on_balance_sheet'].append({
                    'total_paid_from_bills': round(total_paid_from_bills, 2),
                    'balance_sheet_premium_income': round(premium_income, 2),
                    'discrepancy': round(total_paid_from_bills - premium_income, 2),
                    'issue': 'Paid bills not fully reflected on balance sheet'
                })
            
            # 4d. Check for overbilled customers
            for customer_id in set(b.get('customer_id') for b in BILLING.values()):
                if is_suspended_account(customer_id):
                    continue
                    
                customer_bills = [b for b in BILLING.values() if b.get('customer_id') == customer_id]
                customer_policies = [p for p in POLICIES.values() if p.get('customer_id') == customer_id and status_eq(p, 'active')]
                
                if not customer_policies:
                    continue
                
                # Expected monthly premium
                expected_monthly = sum(float(p.get('monthly_premium', 0) or 0) for p in customer_policies)
                
                # Total amount paid in last 30 days
                recent_paid = sum(
                    float(b.get('amount_paid', 0)) for b in customer_bills
                    if b.get('paid_date') and (datetime.now() - datetime.fromisoformat(b['paid_date'].replace('Z', ''))).days <= 30
                )
                
                if expected_monthly > 0 and recent_paid > expected_monthly * 1.5:
                    billing_validation['overbilled_customers'].append({
                        'customer_id': customer_id,
                        'expected_monthly': round(expected_monthly, 2),
                        'recent_paid_30_days': round(recent_paid, 2),
                        'overage': round(recent_paid - expected_monthly, 2),
                        'issue': 'Customer paid significantly more than expected in last 30 days'
                    })
            
            # Generate insight based on billing validation
            total_billing_issues = (
                len(billing_validation['unbilled_customers']) +
                len(billing_validation['duplicate_bills']) +
                len(billing_validation['bills_not_on_balance_sheet']) +
                len(billing_validation['overbilled_customers'])
            )
            
            if total_billing_issues > 0:
                issue_details = []
                if billing_validation['unbilled_customers']:
                    issue_details.append(f"{len(billing_validation['unbilled_customers'])} unbilled customers")
                if billing_validation['duplicate_bills']:
                    issue_details.append(f"{len(billing_validation['duplicate_bills'])} duplicate billing cases")
                if billing_validation['bills_not_on_balance_sheet']:
                    discrepancy = billing_validation['bills_not_on_balance_sheet'][0]['discrepancy']
                    issue_details.append(f"${abs(discrepancy):,.2f} billing discrepancy")
                if billing_validation['overbilled_customers']:
                    issue_details.append(f"{len(billing_validation['overbilled_customers'])} overbilled customers")
                
                insights.append({
                    'type': 'billing_validation',
                    'severity': 'warning' if total_billing_issues < 5 else 'high',
                    'title': 'Billing Validation Issues Detected',
                    'description': f'{total_billing_issues} billing validation issues found: ' + ', '.join(issue_details),
                    'impact': 'Revenue accuracy may be affected - review billing data'
                })
                
                recommendations.append({
                    'priority': 2,
                    'action': 'Review Billing Validation',
                    'details': f'Address {total_billing_issues} billing issues to ensure accurate revenue tracking',
                    'expected_result': 'Improved billing accuracy and customer satisfaction'
                })
            
            if billing_validation['missing_premium_policies']:
                insights.append({
                    'type': 'policy_configuration',
                    'severity': 'warning',
                    'title': 'Policies Missing Premium Configuration',
                    'description': f'{len(billing_validation["missing_premium_policies"])} active policies have no premium amount set',
                    'impact': 'These policies cannot be billed until premium is configured'
                })
            
            # ========== END BILLING VALIDATION CHECKS ==========
            
            # Insight: Premium Collection Status
            if premium_income == 0 and total_monthly_premium_potential > 0:
                insights.append({
                    'type': 'collection_gap',
                    'severity': 'high',
                    'title': 'No Premium Income Collected',
                    'description': f'${total_monthly_premium_potential:,.2f}/month in premiums available but $0 collected. '
                                   f'Total annual premium potential: ${total_annual_premium_potential:,.2f}',
                    'impact': 'Revenue stream not activated - immediate collection action needed'
                })
                recommendations.append({
                    'priority': 1,
                    'action': 'Initiate Premium Collection',
                    'details': f'Process {len(outstanding_bills)} outstanding bills totaling ${total_outstanding:,.2f}',
                    'expected_result': f'Immediate revenue of ${total_outstanding:,.2f}'
                })
            
            # Insight: Claims vs Revenue Balance
            if claims_paid > premium_income and claims_paid > 0:
                insights.append({
                    'type': 'negative_cashflow',
                    'severity': 'warning',
                    'title': 'Claims Exceed Premium Income',
                    'description': f'Claims paid (${claims_paid:,.2f}) exceed premium income (${premium_income:,.2f})',
                    'impact': f'Net loss of ${claims_paid - premium_income:,.2f} funded from reserves'
                })
            
            # Insight: Reserve Health
            if claims_reserve > 0:
                reserve_depletion_rate = claims_paid / max(30, 1)  # Approximate monthly
                months_to_depletion = claims_reserve / reserve_depletion_rate if reserve_depletion_rate > 0 else float('inf')
                
                insights.append({
                    'type': 'reserve_health',
                    'severity': 'info' if months_to_depletion > 24 else 'warning' if months_to_depletion > 12 else 'critical',
                    'title': 'Reserve Adequacy Analysis',
                    'description': f'Claims reserve at ${claims_reserve:,.2f}. At current claim rate, '
                                   f'reserves cover approximately {months_to_depletion:.0f} months of claims.',
                    'impact': 'Reserve position is strong' if months_to_depletion > 60 else 'Monitor reserve levels'
                })
            
            # Insight: Pending Claims Risk
            if total_pending_claims_value > 0:
                pending_to_reserve_ratio = (total_pending_claims_value / claims_reserve * 100) if claims_reserve > 0 else 100
                insights.append({
                    'type': 'pending_claims_exposure',
                    'severity': 'info' if pending_to_reserve_ratio < 5 else 'warning' if pending_to_reserve_ratio < 20 else 'high',
                    'title': 'Pending Claims Exposure',
                    'description': f'{len(pending_claims)} pending claims totaling ${total_pending_claims_value:,.2f} '
                                   f'({pending_to_reserve_ratio:.1f}% of reserves)',
                    'impact': 'Adequate reserves to cover pending claims' if pending_to_reserve_ratio < 10 else 'Review claims queue'
                })
            
            # 5. Projected Financial Outlook (12 months)
            monthly_premium_proj = total_monthly_premium_potential
            avg_monthly_claims = claims_paid / max(1, len(paid_claims)) if paid_claims else 0
            projected_annual_revenue = monthly_premium_proj * 12
            projected_annual_claims = avg_monthly_claims * 12 * len(active_policies) * 0.1  # 10% claim rate assumption
            projected_net = projected_annual_revenue - projected_annual_claims
            
            projections = {
                '12_month_outlook': {
                    'projected_premium_revenue': round(projected_annual_revenue, 2),
                    'projected_claims_expense': round(projected_annual_claims, 2),
                    'projected_net_income': round(projected_net, 2),
                    'projected_reserve_balance': round(claims_reserve - projected_annual_claims + projected_annual_revenue * 0.3, 2),  # 30% to reserves
                    'assumptions': {
                        'claim_rate': '10% of active policies per year',
                        'collection_rate': '100% of premiums',
                        'reserve_contribution': '30% of premium revenue'
                    }
                },
                'breakeven_analysis': {
                    'monthly_breakeven': round(avg_monthly_claims, 2) if avg_monthly_claims > 0 else 0,
                    'current_monthly_capacity': round(monthly_premium_proj, 2),
                    'margin': round(monthly_premium_proj - avg_monthly_claims, 2) if avg_monthly_claims > 0 else monthly_premium_proj
                }
            }
            
            # 6. Data Integrity Score
            integrity_checks = {
                'premium_vs_billing_match': abs(premium_income - total_paid_from_bills) < 1,
                'claims_vs_expense_match': abs(claims_paid - sum(float(c.get('approved_amount', 0)) for c in paid_claims)) < 1,
                'reserve_positive': claims_reserve > 0,
                'audit_trail_present': len(PHINS_BALANCE_SHEET.get('audit_log', [])) > 0
            }
            integrity_score = sum(1 for v in integrity_checks.values() if v) / len(integrity_checks) * 100
            
            self._set_json_headers()
            self.wfile.write(json.dumps({
                'success': True,
                'ai_analysis': {
                    'generated_at': datetime.now().isoformat(),
                    'analysis_type': 'PHINS Balance Sheet AI/BI Intelligence',
                    
                    # Current State
                    'current_state': {
                        'claims_reserve': claims_reserve,
                        'premium_income': premium_income,
                        'claims_paid': claims_paid,
                        'net_income': net_income,
                        'total_revenue': total_revenue,
                        'total_expenses': total_expenses
                    },
                    
                    # Key Metrics
                    'key_metrics': {
                        'loss_ratio_pct': round(loss_ratio, 2) if loss_ratio != float('inf') else 'N/A (no premium)',
                        'collection_rate_pct': round(collection_rate, 2),
                        'active_policies': len(active_policies),
                        'total_policies': len(all_policies),
                        'outstanding_premium': round(total_outstanding, 2),
                        'pending_claims_value': round(total_pending_claims_value, 2)
                    },
                    
                    # AI Insights
                    'insights': insights,
                    
                    # Recommendations
                    'recommendations': recommendations,
                    
                    # Risk Alerts
                    'risk_alerts': risk_alerts if risk_alerts else [{'level': 'low', 'message': 'No immediate risks detected'}],
                    
                    # Projections
                    'projections': projections,
                    
                    # Data Integrity
                    'data_integrity': {
                        'score': round(integrity_score, 1),
                        'status': 'VALID' if integrity_score >= 75 else 'WARNING' if integrity_score >= 50 else 'CRITICAL',
                        'checks': integrity_checks
                    },
                    
                    # Billing Validation (new)
                    'billing_validation': {
                        'total_issues': total_billing_issues,
                        'unbilled_customers': billing_validation['unbilled_customers'],
                        'duplicate_bills': billing_validation['duplicate_bills'],
                        'bills_not_on_balance_sheet': billing_validation['bills_not_on_balance_sheet'],
                        'overbilled_customers': billing_validation['overbilled_customers'],
                        'missing_premium_policies': billing_validation['missing_premium_policies'],
                        'status': 'OK' if total_billing_issues == 0 else 'ISSUES_FOUND'
                    }
                },
                'timestamp': datetime.now().isoformat()
            }, default=str).encode('utf-8'))
            return
        
        # Reserve Integrity Check - Verify claims_reserve matches claims paid
        if path == '/api/admin/balance-sheet/fix-reserve':
            if not require_role(session, ['admin', 'accountant']):
                self._set_json_headers(403)
                self.wfile.write(json.dumps({'error': 'Unauthorized. Admin or Accountant access required.'}).encode('utf-8'))
                return
            
            auto_fix = qs.get('auto_fix', ['false'])[0].lower() == 'true'
            
            initialize_balance_sheet()
            
            # Calculate expected reserve: initial - all claims paid
            INITIAL_RESERVE = 3500000.0  # Initial seed capital
            total_claims_paid = PHINS_BALANCE_SHEET['expense_breakdown']['claims_paid']
            expected_reserve = INITIAL_RESERVE - total_claims_paid
            actual_reserve = PHINS_BALANCE_SHEET['claims_reserve']
            discrepancy = actual_reserve - expected_reserve
            
            result = {
                'success': True,
                'initial_reserve': INITIAL_RESERVE,
                'total_claims_paid': total_claims_paid,
                'expected_reserve': expected_reserve,
                'actual_reserve': actual_reserve,
                'discrepancy': discrepancy,
                'needs_fix': abs(discrepancy) > 0.01
            }
            
            if auto_fix and abs(discrepancy) > 0.01:
                # Fix the claims_reserve
                old_reserve = PHINS_BALANCE_SHEET['claims_reserve']
                PHINS_BALANCE_SHEET['claims_reserve'] = expected_reserve
                PHINS_BALANCE_SHEET['last_updated'] = datetime.now().isoformat()
                
                # Add audit log entry
                PHINS_BALANCE_SHEET['audit_log'].append({
                    'action': 'reserve_integrity_fix',
                    'actor': session.get('username', 'system') if session else 'system',
                    'timestamp': datetime.now().isoformat(),
                    'old_reserve': old_reserve,
                    'new_reserve': expected_reserve,
                    'discrepancy_fixed': discrepancy
                })
                
                # Add correction transaction
                PHINS_BALANCE_SHEET['transactions'].append({
                    'tx_id': f"BS-ADJ-{datetime.now().strftime('%Y%m%d%H%M%S')}-{random.randint(1000, 9999)}",
                    'type': 'adjustment',
                    'category': 'claims_reserve',
                    'amount': -discrepancy,
                    'description': f'Reserve integrity correction for historical claims (discrepancy: ${discrepancy:,.2f})',
                    'actor': session.get('username', 'system') if session else 'system',
                    'balance_after': expected_reserve,
                    'claims_reserve_after': expected_reserve,
                    'timestamp': datetime.now().isoformat()
                })
                
                save_ledger_data()
                
                result['fix_applied'] = True
                result['new_reserve'] = expected_reserve
                result['message'] = f'Reserve corrected from ${old_reserve:,.2f} to ${expected_reserve:,.2f}'
            else:
                result['fix_applied'] = False
                if abs(discrepancy) <= 0.01:
                    result['message'] = 'Reserve is already correct - no fix needed'
                else:
                    result['message'] = f'Discrepancy of ${discrepancy:,.2f} found. Add ?auto_fix=true to correct.'
            
            result['timestamp'] = datetime.now().isoformat()
            
            self._set_json_headers()
            self.wfile.write(json.dumps(result, default=str).encode('utf-8'))
            return
        
        # Balance Sheet Reconciliation - Verify and auto-correct integrity
        if path == '/api/admin/balance-sheet/reconcile':
            # Check authorization - only admin and accountant
            if not require_role(session, ['admin', 'accountant']):
                self._set_json_headers(403)
                self.wfile.write(json.dumps({'error': 'Unauthorized. Admin or Accountant access required.'}).encode('utf-8'))
                return
            
            auto_correct = qs.get('auto_correct', ['false'])[0].lower() == 'true'
            
            initialize_balance_sheet()
            
            # ========== COMPREHENSIVE RECONCILIATION ==========
            # Calculate expected values from actual transaction data
            
            # 1. Premium Income - cumulative paid premiums from billed and
            # unbilled/direct premium flows (with de-duplication safeguards).
            premium_income_totals = calculate_cumulative_premium_income(exclude_suspended=True)
            expected_premium_income = premium_income_totals['total']
            
            # 2. Claims Paid - from paid claims
            expected_claims_paid = sum(
                float(c.get('paid_amount', 0) or c.get('approved_amount', 0)) 
                for c in CLAIMS.values()
                if status_eq(c, 'paid')
            )
            
            # 3. Medical Equipment/Services (Supplier Payments) - from medical purchases
            total_medical_purchases = sum(
                float(p.get('amount', 0)) for p in MEDICAL_PURCHASES.values()
            )
            medical_by_category = {}
            for purchase in MEDICAL_PURCHASES.values():
                cat = purchase.get('category', 'general')
                if cat not in medical_by_category:
                    medical_by_category[cat] = {'count': 0, 'total': 0.0}
                medical_by_category[cat]['count'] += 1
                medical_by_category[cat]['total'] += float(purchase.get('amount', 0))
            
            # 4. Health Wallet Deposits & Transactions
            total_wallet_deposits = 0.0
            total_wallet_balance = 0.0
            wallet_transaction_count = 0
            for wallet in HEALTH_WALLETS.values():
                total_wallet_balance += float(wallet.get('balance', 0))
                for tx in wallet.get('transactions', []):
                    wallet_transaction_count += 1
                    if tx.get('type') in ['deposit', 'initial_deposit']:
                        total_wallet_deposits += float(tx.get('amount', 0))
            
            # 5. Investment Accounts
            total_investment_balance = 0.0
            total_investment_deposits = 0.0
            investment_by_type = {'index': 0.0, 'bonds': 0.0, 'crypto': 0.0}
            for account in INVESTMENT_ACCOUNTS.values():
                total_investment_balance += float(account.get('balance', 0))
                investment_by_type['index'] += float(account.get('index_balance', 0))
                investment_by_type['bonds'] += float(account.get('bonds_balance', 0))
                investment_by_type['crypto'] += float(account.get('crypto_balance', 0))
                for dep in account.get('deposits', []):
                    total_investment_deposits += float(dep.get('amount', 0))
            
            # 6. Supplier Offers/Payments
            total_supplier_offers = len(SUPPLIER_OFFERS)
            supplier_offer_value = sum(
                float(o.get('price', 0) or o.get('amount', 0)) for o in SUPPLIER_OFFERS.values()
            )
            
            # 7. Calculate from transaction ledger as secondary source
            ledger_premium_income = premium_income_totals['ledger_unbilled_total']
            ledger_claims_paid = sum(
                tx.get('amount', 0) for tx in TRANSACTION_LEDGER.values()
                if get_transaction_type(tx) in ['claim_payment', 'claim_paid', 'claims_paid']
            )
            ledger_medical_payments = sum(
                tx.get('amount', 0) for tx in TRANSACTION_LEDGER.values()
                if get_transaction_type(tx) in ['medical_purchase', 'supplier_payment', 'health_wallet_purchase']
            )
            
            # Current values in balance sheet
            current_premium_income = PHINS_BALANCE_SHEET['revenue_breakdown']['premium_income']
            current_claims_paid = PHINS_BALANCE_SHEET['expense_breakdown']['claims_paid']
            current_supplier_payments = PHINS_BALANCE_SHEET['expense_breakdown']['supplier_payments']
            
            # ========== DISCREPANCY DETECTION ==========
            discrepancies = []
            corrections = []
            
            premium_diff = abs(expected_premium_income - current_premium_income)
            claims_diff = abs(expected_claims_paid - current_claims_paid)
            supplier_diff = abs(total_medical_purchases - current_supplier_payments)
            
            if premium_diff > 0.01:
                discrepancies.append({
                    'field': 'premium_income',
                    'label': 'Premium Income',
                    'expected': expected_premium_income,
                    'current': current_premium_income,
                    'difference': expected_premium_income - current_premium_income,
                    'source': 'billed_plus_unbilled_premium_payments'
                })
                
                if auto_correct:
                    PHINS_BALANCE_SHEET['revenue_breakdown']['premium_income'] = expected_premium_income
                    old_total = PHINS_BALANCE_SHEET['total_revenue']
                    PHINS_BALANCE_SHEET['total_revenue'] = sum(PHINS_BALANCE_SHEET['revenue_breakdown'].values())
                    corrections.append(f'Premium income updated: ${current_premium_income:.2f} -> ${expected_premium_income:.2f}')
                    corrections.append(f'Total revenue updated: ${old_total:.2f} -> ${PHINS_BALANCE_SHEET["total_revenue"]:.2f}')
            
            if claims_diff > 0.01:
                discrepancies.append({
                    'field': 'claims_paid',
                    'label': 'Claims Paid',
                    'expected': expected_claims_paid,
                    'current': current_claims_paid,
                    'difference': expected_claims_paid - current_claims_paid,
                    'source': 'paid_claims'
                })
                
                if auto_correct:
                    PHINS_BALANCE_SHEET['expense_breakdown']['claims_paid'] = expected_claims_paid
                    old_total = PHINS_BALANCE_SHEET['total_expenses']
                    PHINS_BALANCE_SHEET['total_expenses'] = sum(PHINS_BALANCE_SHEET['expense_breakdown'].values())
                    corrections.append(f'Claims paid updated: ${current_claims_paid:.2f} -> ${expected_claims_paid:.2f}')
                    corrections.append(f'Total expenses updated: ${old_total:.2f} -> ${PHINS_BALANCE_SHEET["total_expenses"]:.2f}')
            
            if supplier_diff > 0.01:
                discrepancies.append({
                    'field': 'supplier_payments',
                    'label': 'Medical Equipment/Services (Suppliers)',
                    'expected': total_medical_purchases,
                    'current': current_supplier_payments,
                    'difference': total_medical_purchases - current_supplier_payments,
                    'source': 'medical_purchases'
                })
                
                if auto_correct:
                    PHINS_BALANCE_SHEET['expense_breakdown']['supplier_payments'] = total_medical_purchases
                    old_total = PHINS_BALANCE_SHEET['total_expenses']
                    PHINS_BALANCE_SHEET['total_expenses'] = sum(PHINS_BALANCE_SHEET['expense_breakdown'].values())
                    corrections.append(f'Supplier payments updated: ${current_supplier_payments:.2f} -> ${total_medical_purchases:.2f}')
                    corrections.append(f'Total expenses updated: ${old_total:.2f} -> ${PHINS_BALANCE_SHEET["total_expenses"]:.2f}')
            
            # Update timestamp if corrections were made
            if corrections:
                PHINS_BALANCE_SHEET['last_updated'] = datetime.now().isoformat()
                PHINS_BALANCE_SHEET['audit_log'].append({
                    'action': 'reconciliation_auto_correct',
                    'actor': session.get('username', 'system') if session else 'system',
                    'timestamp': datetime.now().isoformat(),
                    'corrections': corrections,
                    'discrepancies_found': len(discrepancies)
                })
                save_ledger_data()
            
            is_valid = len(discrepancies) == 0
            
            # ========== COMPREHENSIVE REPORT ==========
            self._set_json_headers()
            self.wfile.write(json.dumps({
                'success': True,
                'is_valid': is_valid,
                'discrepancies': discrepancies,
                'corrections_made': corrections,
                'auto_correct_enabled': auto_correct,
                
                # Detailed validation sources
                'validation_sources': {
                    'premium_income': {
                        'from_bills': premium_income_totals['from_bills'],
                        'from_ledger': ledger_premium_income,
                        'from_ledger_unbilled': premium_income_totals['ledger_unbilled_total'],
                        'current': current_premium_income,
                        'bills_count': premium_income_totals['paid_bills_count'],
                        'ledger_unbilled_count': premium_income_totals['ledger_unbilled_count']
                    },
                    'claims_paid': {
                        'from_claims': expected_claims_paid,
                        'from_ledger': ledger_claims_paid,
                        'current': current_claims_paid,
                        'paid_claims_count': len([c for c in CLAIMS.values() if status_eq(c, 'paid')])
                    },
                    'supplier_payments': {
                        'from_medical_purchases': total_medical_purchases,
                        'from_ledger': ledger_medical_payments,
                        'current': current_supplier_payments,
                        'purchases_count': len(MEDICAL_PURCHASES)
                    }
                },
                
                # Medical Equipment/Services Breakdown
                'medical_services': {
                    'total_amount': total_medical_purchases,
                    'total_transactions': len(MEDICAL_PURCHASES),
                    'by_category': medical_by_category
                },
                
                # Health Wallet Summary
                'health_wallets': {
                    'total_balance': total_wallet_balance,
                    'total_deposits': total_wallet_deposits,
                    'active_wallets': len(HEALTH_WALLETS),
                    'total_transactions': wallet_transaction_count
                },
                
                # Investment Accounts Summary
                'investments': {
                    'total_balance': total_investment_balance,
                    'total_deposits': total_investment_deposits,
                    'active_accounts': len(INVESTMENT_ACCOUNTS),
                    'by_type': investment_by_type
                },
                
                # Supplier Ecosystem
                'suppliers': {
                    'total_offers': total_supplier_offers,
                    'total_offer_value': supplier_offer_value
                },
                
                # Current Balance Sheet
                'current_balance_sheet': {
                    'claims_reserve': PHINS_BALANCE_SHEET['claims_reserve'],
                    'operating_reserve': PHINS_BALANCE_SHEET['operating_reserve'],
                    'supplier_reserve': PHINS_BALANCE_SHEET['supplier_reserve'],
                    'investment_reserve': PHINS_BALANCE_SHEET['investment_reserve'],
                    'total_revenue': PHINS_BALANCE_SHEET['total_revenue'],
                    'total_expenses': PHINS_BALANCE_SHEET['total_expenses'],
                    'net_income': PHINS_BALANCE_SHEET['total_revenue'] - PHINS_BALANCE_SHEET['total_expenses'],
                    'revenue_breakdown': PHINS_BALANCE_SHEET['revenue_breakdown'],
                    'expense_breakdown': PHINS_BALANCE_SHEET['expense_breakdown']
                },
                
                # Summary totals for quick reference
                'summary_totals': {
                    'total_premiums_collected': expected_premium_income,
                    'premium_income_breakdown': {
                        'from_bills': premium_income_totals['from_bills'],
                        'from_ledger': premium_income_totals['ledger_unbilled_total'],
                        'total': expected_premium_income
                    },
                    'total_claims_paid': expected_claims_paid,
                    'total_medical_services': total_medical_purchases,
                    'total_wallet_deposits': total_wallet_deposits,
                    'total_investments': total_investment_balance,
                    'net_position': expected_premium_income - expected_claims_paid - total_medical_purchases
                },
                
                # Top-level cumulative premium echo
                'cumulative_premium': expected_premium_income,
                
                'timestamp': datetime.now().isoformat()
            }, default=str).encode('utf-8'))
            return
        
        # ========== BILL ALL POLICIES API ==========
        # AI Insights Action: Bill all active policies systematically
        # Triggered from AI Recommendations "Priority 1: Initiate Premium Collection"
        
        if path == '/api/admin/bill-all-policies':
            # Check authorization - only admin and accountant
            if not require_role(session, ['admin', 'accountant']):
                self._set_json_headers(403)
                self.wfile.write(json.dumps({'error': 'Unauthorized. Admin or Accountant access required.'}).encode('utf-8'))
                return
            
            initialize_balance_sheet()
            
            # Get the actor for audit trail
            actor = 'system'
            if session:
                actor = session.get('username', 'admin')
            
            # ========== SYSTEMATIC BILLING EXECUTION ==========
            
            # 1. Get all active policies
            active_policies = [p for p in POLICIES.values() if status_eq(p, 'active')]
            
            # 2. Get existing outstanding bills (to avoid duplicate billing)
            existing_outstanding_bills = {
                b.get('policy_id'): b 
                for b in BILLING.values() 
                if b.get('status') in ['outstanding', 'partial'] and b.get('policy_id')
            }
            
            # 3. Track billing results
            billing_results = {
                'total_policies': len(active_policies),
                'already_billed': 0,
                'newly_billed': 0,
                'skipped': 0,
                'skipped_no_premium': 0,
                'skipped_suspended': 0,
                'total_amount_billed': 0.0,
                'bills_created': [],
                'policies_skipped': [],
                'policies_eligible': [],  # Policies that COULD be billed but weren't
                'ledger_entries': [],
                'balance_sheet_updated': False,
                'errors': []
            }
            
            # 4. Process each active policy
            for policy in active_policies:
                policy_id = policy.get('id') or policy.get('policy_id')
                customer_id = policy.get('customer_id')
                
                # Skip if policy already has an outstanding bill
                if policy_id in existing_outstanding_bills:
                    billing_results['already_billed'] += 1
                    billing_results['policies_skipped'].append({
                        'policy_id': policy_id,
                        'reason': 'outstanding_bill_exists',
                        'existing_bill_id': existing_outstanding_bills[policy_id].get('bill_id') or existing_outstanding_bills[policy_id].get('id')
                    })
                    continue
                
                # Skip suspended accounts
                if is_suspended_account(customer_id):
                    billing_results['skipped'] += 1
                    billing_results['skipped_suspended'] += 1
                    billing_results['policies_skipped'].append({
                        'policy_id': policy_id,
                        'customer_id': customer_id,
                        'reason': 'suspended_account'
                    })
                    continue
                
                # Skip if no valid premium amount
                monthly_premium = float(policy.get('monthly_premium', 0) or policy.get('premium', 0) or 0)
                annual_premium = float(policy.get('annual_premium', 0) or 0)
                
                # Calculate billing amount based on billing frequency
                billing_frequency = policy.get('billing_frequency', 'monthly').lower()
                if billing_frequency == 'annual':
                    bill_amount = annual_premium if annual_premium > 0 else monthly_premium * 12
                elif billing_frequency == 'quarterly':
                    bill_amount = (annual_premium / 4) if annual_premium > 0 else monthly_premium * 3
                else:  # monthly (default)
                    bill_amount = monthly_premium if monthly_premium > 0 else (annual_premium / 12 if annual_premium > 0 else 0)
                
                if bill_amount <= 0:
                    billing_results['skipped'] += 1
                    billing_results['skipped_no_premium'] += 1
                    billing_results['policies_skipped'].append({
                        'policy_id': policy_id,
                        'customer_id': customer_id,
                        'reason': 'no_premium_amount',
                        'monthly_premium': monthly_premium,
                        'annual_premium': annual_premium
                    })
                    continue
                
                try:
                    # 5. Create the bill
                    bill_id = f"BILL-{datetime.now().strftime('%Y%m%d')}-{random.randint(10000, 99999)}"
                    due_days = 30 if billing_frequency == 'monthly' else (90 if billing_frequency == 'quarterly' else 365)
                    
                    bill = {
                        'id': bill_id,
                        'bill_id': bill_id,
                        'policy_id': policy_id,
                        'customer_id': customer_id,
                        'amount': round(bill_amount, 2),
                        'amount_due': round(bill_amount, 2),
                        'amount_paid': 0.0,
                        'status': 'outstanding',
                        'billing_frequency': billing_frequency,
                        'billing_period': datetime.now().strftime('%Y-%m'),
                        'created_date': datetime.now().isoformat(),
                        'due_date': (datetime.now() + timedelta(days=due_days)).isoformat(),
                        'description': f"Premium billing for policy {policy_id}",
                        'generated_by': 'ai_insights_bill_all',
                        'actor': actor
                    }
                    
                    # Store the bill
                    BILLING[bill_id] = bill
                    
                    # 6. Record transaction on ledger
                    ledger_tx = record_transaction(
                        customer_id=customer_id,
                        tx_type='billing_created',
                        amount=bill_amount,
                        description=f"Bill {bill_id} created for policy {policy_id} via AI Insights Bill All action",
                        metadata={
                            'bill_id': bill_id,
                            'policy_id': policy_id,
                            'billing_frequency': billing_frequency,
                            'due_date': bill['due_date'],
                            'generated_by': 'ai_insights_bill_all'
                        }
                    )
                    
                    # 7. Track results
                    billing_results['newly_billed'] += 1
                    billing_results['total_amount_billed'] += bill_amount
                    billing_results['bills_created'].append({
                        'bill_id': bill_id,
                        'policy_id': policy_id,
                        'customer_id': customer_id,
                        'amount': round(bill_amount, 2),
                        'due_date': bill['due_date'],
                        'billing_frequency': billing_frequency
                    })
                    billing_results['ledger_entries'].append(ledger_tx)
                    
                    # 8. Audit logging
                    if audit:
                        try:
                            audit.log(actor, 'create', 'bill', bill_id, {
                                'policy_id': policy_id,
                                'amount': bill_amount,
                                'trigger': 'ai_insights_bill_all'
                            })
                        except Exception:
                            pass
                    
                except Exception as bill_error:
                    billing_results['errors'].append({
                        'policy_id': policy_id,
                        'error': str(bill_error)
                    })
            
            # 9. Update PHINS Balance Sheet with billing summary
            # Note: Premium revenue is only recorded when bills are PAID, not when created
            # But we record the expected receivable in audit log
            if billing_results['newly_billed'] > 0:
                # Add audit entry for bulk billing action
                PHINS_BALANCE_SHEET['audit_log'].append({
                    'action': 'ai_insights_bill_all',
                    'actor': actor,
                    'timestamp': datetime.now().isoformat(),
                    'details': f"Bulk billing initiated: {billing_results['newly_billed']} bills created totaling ${billing_results['total_amount_billed']:,.2f}",
                    'bills_created': billing_results['newly_billed'],
                    'amount_billed': billing_results['total_amount_billed']
                })
                PHINS_BALANCE_SHEET['last_updated'] = datetime.now().isoformat()
                billing_results['balance_sheet_updated'] = True
            
            # 10. Save all changes to persistent storage
            save_ledger_data()
            
            # 11. Database persistence if enabled
            if USE_DATABASE and database_enabled:
                try:
                    from database.manager import DatabaseManager
                    with DatabaseManager() as db:
                        for bill_info in billing_results['bills_created']:
                            try:
                                db.billing.create(
                                    id=bill_info['bill_id'],
                                    policy_id=bill_info['policy_id'],
                                    customer_id=bill_info['customer_id'],
                                    amount_due=bill_info['amount'],
                                    amount_paid=0.0,
                                    status='outstanding',
                                    due_date=bill_info['due_date']
                                )
                            except Exception:
                                pass  # Bill may already exist in DB
                except Exception as db_err:
                    billing_results['errors'].append({
                        'type': 'database_sync',
                        'error': str(db_err)
                    })
            
            # 12. Prepare response with reconciliation summary
            total_outstanding_after = sum(
                float(b.get('amount', b.get('amount_due', 0))) - float(b.get('amount_paid', 0))
                for b in BILLING.values()
                if b.get('status') in ['outstanding', 'partial']
            )
            
            # Generate detailed message based on results
            if billing_results['newly_billed'] > 0:
                message = f"Successfully created {billing_results['newly_billed']} bills totaling ${billing_results['total_amount_billed']:,.2f}. {billing_results['already_billed']} policies already had outstanding bills."
            elif billing_results['total_policies'] == 0:
                message = "No active policies found in the system. Please ensure policies are created and approved before billing."
            elif billing_results['already_billed'] == billing_results['total_policies']:
                message = f"All {billing_results['total_policies']} active policies already have outstanding bills. No new bills needed."
            elif billing_results['skipped_no_premium'] > 0 and billing_results['already_billed'] == 0:
                message = f"No bills created. {billing_results['skipped_no_premium']} policies have no premium amount configured. Please set monthly_premium or annual_premium on these policies."
            else:
                reasons = []
                if billing_results['already_billed'] > 0:
                    reasons.append(f"{billing_results['already_billed']} already have outstanding bills")
                if billing_results['skipped_no_premium'] > 0:
                    reasons.append(f"{billing_results['skipped_no_premium']} have no premium amount set")
                if billing_results['skipped_suspended'] > 0:
                    reasons.append(f"{billing_results['skipped_suspended']} are suspended test accounts")
                message = f"No new bills created. {billing_results['total_policies']} active policies analyzed: " + "; ".join(reasons) if reasons else "No billable policies found."
            
            # Detailed skip analysis for zero-bill scenarios
            skip_analysis = {
                'total_active_policies': billing_results['total_policies'],
                'already_billed': billing_results['already_billed'],
                'skipped_no_premium': billing_results['skipped_no_premium'],
                'skipped_suspended': billing_results['skipped_suspended'],
                'other_skipped': billing_results['skipped'] - billing_results['skipped_no_premium'] - billing_results['skipped_suspended'],
                'eligible_but_not_billed': billing_results['total_policies'] - billing_results['already_billed'] - billing_results['skipped'],
                'recommendation': None
            }
            
            # Add recommendation based on analysis
            if billing_results['skipped_no_premium'] > 0:
                skip_analysis['recommendation'] = 'Configure premium amounts on policies with missing premiums'
            elif billing_results['total_policies'] == 0:
                skip_analysis['recommendation'] = 'Create and approve customer policies before billing'
            elif billing_results['already_billed'] == billing_results['total_policies']:
                skip_analysis['recommendation'] = 'Collect payments on existing outstanding bills before generating new ones'
            
            response = {
                'success': True,
                'action': 'bill_all_policies',
                'triggered_by': 'ai_insights_premium_collection',
                'actor': actor,
                'timestamp': datetime.now().isoformat(),
                
                # Billing summary
                'summary': {
                    'total_active_policies': billing_results['total_policies'],
                    'bills_created': billing_results['newly_billed'],
                    'already_billed': billing_results['already_billed'],
                    'skipped': billing_results['skipped'],
                    'skipped_no_premium': billing_results['skipped_no_premium'],
                    'skipped_suspended': billing_results['skipped_suspended'],
                    'total_amount_billed': round(billing_results['total_amount_billed'], 2),
                    'errors_count': len(billing_results['errors'])
                },
                
                # Skip analysis for debugging zero-bill scenarios
                'skip_analysis': skip_analysis,
                
                # Created bills details
                'bills_created': billing_results['bills_created'][:50],  # Limit to first 50 for response size
                
                # Skipped policies (for debugging)
                'policies_skipped': billing_results['policies_skipped'][:20],  # Limit to first 20
                
                # Data integrity confirmation
                'data_integrity': {
                    'ledger_entries_created': len(billing_results['ledger_entries']),
                    'balance_sheet_updated': billing_results['balance_sheet_updated'],
                    'persistent_storage_saved': True,
                    'database_synced': USE_DATABASE and database_enabled
                },
                
                # Current outstanding totals for dashboard update
                'current_state': {
                    'total_outstanding_amount': round(total_outstanding_after, 2),
                    'total_outstanding_bills': len([b for b in BILLING.values() if b.get('status') in ['outstanding', 'partial']]),
                    'total_paid_bills': len([b for b in BILLING.values() if b.get('status') == 'paid']),
                    'premium_income_collected': PHINS_BALANCE_SHEET['revenue_breakdown']['premium_income']
                },
                
                # Errors if any
                'errors': billing_results['errors'] if billing_results['errors'] else None,
                
                # Message for UI
                'message': message
            }
            
            self._set_json_headers()
            self.wfile.write(json.dumps(response, default=str).encode('utf-8'))
            return
        
        # ========== END BILL ALL POLICIES API ==========
        
        # ========== END PHINS BALANCE SHEET API ==========
        
        # ========== SUSPENDED TEST ACCOUNTS MANAGEMENT API ==========
        
        # Get suspended accounts list
        if path == '/api/admin/suspended-accounts':
            if not require_role(session, ['admin']):
                self._set_json_headers(403)
                self.wfile.write(json.dumps({'error': 'Unauthorized. Admin access required.'}).encode('utf-8'))
                return
            
            # Get details of suspended accounts
            suspended_details = []
            for cust_id in SUSPENDED_TEST_ACCOUNTS:
                customer = CUSTOMERS.get(cust_id, {})
