                    TOKEN_REGISTRY['TK-ETH'] = {'id': 'TK-ETH', 'symbol': 'ETH', 'name': 'Ethereum', 'asset_type': 'currency', 'enabled': True, 'classification': 'internal', 'created_by': 'system', 'created_date': datetime.now().isoformat()}

