        # ========== END SECURE NOTIFICATION PIPELINE POST API ==========
        
        # ========== END BILLING API ==========
        # Minimal billing endpoints (demo fallback when engine routes are not used)
        if path == '/api/billing/create':
            try:
                data = json.loads(body)
                policy_id = data.get('policy_id')
                amount_due = float(data.get('amount_due', 0))
                due_days = int(data.get('due_days', 30))
                if not policy_id or not validate_amount(amount_due):
                    self._set_json_headers(400)
                    self.wfile.write(json.dumps({'error': 'policy_id and valid amount_due required'}).encode('utf-8'))
                    return
                bill_id = f"BILL-{datetime.now().strftime('%Y%m%d')}-{random.randint(1000,9999)}"
                policy = POLICIES.get(policy_id, {}) if policy_id else {}
                customer_id = policy.get('customer_id')
                bill = {
                    # Compatibility: some tests/clients expect bill_id, others expect id
                    'id': bill_id,
                    'bill_id': bill_id,
                    'policy_id': policy_id,
                    # Compatibility: amount_due is the canonical field name
                    'amount_due': amount_due,
                    'amount': amount_due,
                    'amount_paid': 0.0,
                    'status': 'outstanding',
                    'created_date': datetime.now().isoformat(),
                    'due_date': (datetime.now() + timedelta(days=due_days)).isoformat(),
                    'customer_id': customer_id
                }
                BILLING[bill_id] = bill
                if audit:
                    try:
                        audit.log('system', 'create', 'bill', bill_id, {'policy_id': policy_id, 'amount_due': amount_due})
                    except Exception:
                        pass
                self._set_json_headers(201)
                self.wfile.write(json.dumps({'bill': bill}).encode('utf-8'))
            except Exception as e:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': 'Invalid request', 'details': str(e)}).encode('utf-8'))
            return

        if path == '/api/billing/pay':
            try:
                data = json.loads(body)
                bill_id = data.get('bill_id')
                amount = float(data.get('amount', 0))
                payment_method = data.get('payment_method', 'card')
                bill = BILLING.get(bill_id)
                if not bill:
                    self._set_json_headers(404)
                    self.wfile.write(json.dumps({'error': 'Bill not found'}).encode('utf-8'))
                    return
                if not validate_amount(amount):
                    self._set_json_headers(400)
                    self.wfile.write(json.dumps({'error': 'Invalid amount'}).encode('utf-8'))
                    return
                
                # Get customer_id from bill
                customer_id = bill.get('customer_id', 'unknown')
                policy_id = bill.get('policy_id')
                
                # Handle health_wallet payment method
                wallet_deduction_info = None
                if payment_method == 'health_wallet':
                    # Check if customer has sufficient health wallet balance
                    wallet = HEALTH_WALLETS.get(customer_id, {})
                    wallet_balance = wallet.get('balance', 0)
                    
                    if wallet_balance < amount:
                        self._set_json_headers(400)
                        self.wfile.write(json.dumps({
                            'error': 'Insufficient health wallet balance',
                            'wallet_balance': wallet_balance,
                            'amount_required': amount,
                            'shortfall': amount - wallet_balance
                        }).encode('utf-8'))
                        return
                    
                    # Deduct from health wallet
                    prev_wallet_balance = wallet_balance
                    HEALTH_WALLETS[customer_id]['balance'] -= amount
                    new_wallet_balance = HEALTH_WALLETS[customer_id]['balance']
                    
                    # Record wallet withdrawal transaction
                    wallet_tx = {
                        'id': f"WAL-PAY-{datetime.now().strftime('%Y%m%d%H%M%S')}-{random.randint(1000, 9999)}",
                        'type': 'premium_payment',
                        'amount': -amount,
                        'bill_id': bill_id,
                        'policy_id': policy_id,
                        'description': f"Premium payment for bill {bill_id}",
                        'previous_balance': prev_wallet_balance,
                        'balance_after': new_wallet_balance,
                        'timestamp': datetime.now().isoformat()
                    }
                    HEALTH_WALLETS[customer_id]['transactions'].append(wallet_tx)
                    
                    wallet_deduction_info = {
                        'previous_balance': prev_wallet_balance,
                        'amount_deducted': amount,
                        'new_balance': new_wallet_balance,
                        'wallet_tx_id': wallet_tx['id']
                    }
                
                prev_paid = bill.get('amount_paid', 0.0)
                bill['amount_paid'] = prev_paid + amount
                # Support both 'amount' and 'amount_due' field names for compatibility
                amount_due = bill.get('amount', bill.get('amount_due', 0))
                if bill['amount_paid'] >= amount_due:
                    bill['status'] = 'paid'
                    bill['paid_date'] = datetime.now().isoformat()
                else:
                    bill['status'] = 'partial'
                
                bill['payment_method'] = payment_method
                
                # EXPLICIT: Re-assign to ensure BILLING is updated
                BILLING[bill_id] = bill
                
                # Record premium revenue on PHINS Balance Sheet
                try:
                    record_premium_revenue(
                        customer_id=customer_id,
                        policy_id=policy_id,
                        amount=amount,
                        description=f"Premium payment for {bill_id} via {payment_method}"
                    )
                except Exception as bs_err:
                    print(f"[BALANCE_SHEET] Error recording premium revenue: {bs_err}")
                
                # Force save to persistence
                save_ledger_data()
                
                # Record payment on TRANSACTION_LEDGER and NFT_LEDGER
                payment_tx = record_transaction(
                    customer_id=customer_id,
                    tx_type='premium_payment' if payment_method == 'health_wallet' else 'bill_payment',
                    amount=amount,
                    description=f"Bill payment of ${amount:.2f} for bill {bill_id} via {payment_method}",
                    metadata={
                        'bill_id': bill_id,
                        'policy_id': policy_id,
                        'payment_method': payment_method,
                        'amount_due': amount_due,
                        'amount_paid_total': bill['amount_paid'],
                        'bill_status': bill['status'],
                        'prev_paid': prev_paid,
                        'wallet_deduction': wallet_deduction_info
                    }
                )
                
                # If payment allocates to savings (for premium payments), route through pipeline
                if savings_pipeline_enabled and savings_pipeline_service and policy_id:
                    try:
                        # Get customer's allocation preferences
                        customer_alloc = CUSTOMER_ALLOCATIONS.get(customer_id, {})
                        savings_pct = customer_alloc.get('savings_pct', 75)
                        savings_amount = amount * (savings_pct / 100)
                        
                        if savings_amount > 0:
                            # Deposit to pipeline for AI allocation
                            savings_pipeline_service.deposit_to_pipeline(
                                customer_id=customer_id,
                                amount=savings_amount,
                                source='premium_payment',
                                auto_allocate=True
                            )
                    except Exception as pipe_err:
                        print(f"Pipeline allocation note: {pipe_err}")
                
                if audit:
                    try:
                        audit.log('system', 'update', 'bill', bill_id, {'paid': amount, 'status': bill['status'], 'method': payment_method})
                    except Exception:
                        pass
                
                response_data = {
                    'success': True,
                    'bill': bill,
                    'transaction_recorded': True,
                    'nft_token_id': payment_tx.get('nft_token_id'),
                    'payment_method': payment_method,
                    'amount_paid': amount,
                    'revenue_recorded': True
                }
                
                # Include wallet deduction info if paid from health wallet
                if wallet_deduction_info:
                    response_data['wallet_deduction'] = wallet_deduction_info
                    response_data['message'] = f'Bill paid from health wallet. New wallet balance: ${wallet_deduction_info["new_balance"]:,.2f}'
                
                self._set_json_headers(200)
                self.wfile.write(json.dumps(response_data, default=str).encode('utf-8'))
            except Exception as e:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': 'Invalid request', 'details': str(e)}).encode('utf-8'))
            return
        
        # ========== CUSTOMER BILLING & SETTINGS ENDPOINTS ==========
        
        # Pay all outstanding bills from health wallet
        if path == '/api/billing/pay-all-from-wallet':
            try:
                data = json.loads(body)
                customer_id = data.get('customer_id')
                
                if not customer_id:
                    self._set_json_headers(400)
                    self.wfile.write(json.dumps({'error': 'customer_id required'}).encode('utf-8'))
                    return
                
                # Get customer's health wallet
                wallet = HEALTH_WALLETS.get(customer_id, {})
                wallet_balance = wallet.get('balance', 0)
                
                # Get all outstanding bills for this customer (case-insensitive)
                customer_bills = [
                    (bid, b) for bid, b in BILLING.items() 
                    if b.get('customer_id') == customer_id and status_in(b, ['outstanding', 'partial', 'overdue'])
                ]
                
                if not customer_bills:
                    self._set_json_headers(200)
                    self.wfile.write(json.dumps({
                        'success': True,
                        'message': 'No outstanding bills to pay',
                        'bills_paid': 0,
                        'wallet_balance': wallet_balance
                    }).encode('utf-8'))
                    return
                
                # Calculate total outstanding
                total_outstanding = sum(
                    (b.get('amount', b.get('amount_due', 0)) - b.get('amount_paid', 0))
                    for _, b in customer_bills
                )
                
                # Determine how much can be paid
                amount_to_pay = min(wallet_balance, total_outstanding)
                
                if amount_to_pay <= 0:
                    self._set_json_headers(400)
                    self.wfile.write(json.dumps({
                        'error': 'Insufficient wallet balance or no amount due',
                        'wallet_balance': wallet_balance,
                        'total_outstanding': total_outstanding
                    }).encode('utf-8'))
                    return
                
                # Process payments for each bill
                payments_made = []
                remaining_to_pay = amount_to_pay
                prev_wallet_balance = wallet_balance
                
                for bill_id, bill in customer_bills:
                    if remaining_to_pay <= 0:
                        break
                    
                    amount_due = bill.get('amount', bill.get('amount_due', 0))
                    amount_paid = bill.get('amount_paid', 0)
                    bill_remaining = amount_due - amount_paid
                    
                    if bill_remaining <= 0:
                        continue
                    
                    # Pay this bill (full or partial)
                    payment_amount = min(remaining_to_pay, bill_remaining)
                    
                    bill['amount_paid'] = amount_paid + payment_amount
                    if bill['amount_paid'] >= amount_due:
                        bill['status'] = 'paid'
                        bill['paid_date'] = datetime.now().isoformat()
                    else:
                        bill['status'] = 'partial'
                    bill['payment_method'] = 'health_wallet'
                    BILLING[bill_id] = bill
                    
                    # Record premium revenue on balance sheet
                    try:
                        record_premium_revenue(
                            customer_id=customer_id,
                            policy_id=bill.get('policy_id'),
                            amount=payment_amount,
                            description=f"Premium payment for {bill_id} from health wallet"
                        )
                    except Exception as bs_err:
                        print(f"[BALANCE_SHEET] Error: {bs_err}")
                    
                    payments_made.append({
                        'bill_id': bill_id,
                        'policy_id': bill.get('policy_id'),
                        'amount_paid': payment_amount,
                        'bill_status': bill['status'],
                        'amount_due': amount_due,
                        'total_paid': bill['amount_paid']
                    })
                    
                    remaining_to_pay -= payment_amount
                
                # Deduct total from health wallet
                total_paid = amount_to_pay - remaining_to_pay
                HEALTH_WALLETS[customer_id]['balance'] -= total_paid
                new_wallet_balance = HEALTH_WALLETS[customer_id]['balance']
                
                # Record wallet transaction
                wallet_tx = {
                    'id': f"WAL-BULK-{datetime.now().strftime('%Y%m%d%H%M%S')}-{random.randint(1000, 9999)}",
                    'type': 'bulk_premium_payment',
                    'amount': -total_paid,
                    'bills_paid': len(payments_made),
                    'description': f"Bulk premium payment for {len(payments_made)} bills",
                    'previous_balance': prev_wallet_balance,
                    'balance_after': new_wallet_balance,
                    'timestamp': datetime.now().isoformat()
                }
                HEALTH_WALLETS[customer_id]['transactions'].append(wallet_tx)
                
                # Record on transaction ledger
                payment_tx = record_transaction(
                    customer_id=customer_id,
                    tx_type='bulk_premium_payment',
                    amount=-total_paid,
                    description=f"Bulk premium payment of ${total_paid:.2f} for {len(payments_made)} bills from health wallet",
                    metadata={
                        'bills_paid': payments_made,
                        'total_paid': total_paid,
                        'wallet_previous_balance': prev_wallet_balance,
                        'wallet_new_balance': new_wallet_balance,
                        'remaining_outstanding': total_outstanding - total_paid
                    }
                )
                
                save_ledger_data()
                
                self._set_json_headers(200)
                self.wfile.write(json.dumps({
                    'success': True,
                    'message': f'Paid {len(payments_made)} bills totaling ${total_paid:,.2f} from health wallet',
                    'total_paid': total_paid,
                    'bills_paid': len(payments_made),
                    'payment_details': payments_made,
                    'wallet_previous_balance': prev_wallet_balance,
                    'wallet_new_balance': new_wallet_balance,
                    'remaining_outstanding': total_outstanding - total_paid,
                    'nft_token_id': payment_tx.get('nft_token_id'),
                    'wallet_tx_id': wallet_tx['id']
                }, default=str).encode('utf-8'))
            except Exception as e:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': str(e)}).encode('utf-8'))
            return
        
        # ========== AUTO-PAY AI COMMAND ENDPOINT ==========
        # Configure automatic billing with AI scheduling
        if path == '/api/billing/auto-pay/configure':
            """
            Configure Auto-Pay AI for a policy.
            
            Body params:
            - customer_id: Customer ID (required)
            - policy_id: Policy ID (required)
            - enabled: Enable/disable auto-pay (default true)
            - payment_method: Payment method (credit_card, bank_transfer, health_wallet)
            - card_last4: Last 4 digits of card (for display)
            - card_type: Card type (visa, mastercard, amex, etc.)
            - billing_frequency: monthly, quarterly, annual
            - billing_day: Day of month for billing (1-28)
            - max_amount: Maximum auto-pay amount (optional safety limit)
            - notify_before: Days before to send notification (default 3)
            - ai_optimization: Enable AI to optimize payment timing (default true)
            
            Example: Monthly auto-pay on 1st of month with credit card
            {
                "customer_id": "CUST001",
                "policy_id": "POL001",
                "enabled": true,
                "payment_method": "credit_card",
                "card_last4": "4242",
                "card_type": "visa",
                "billing_frequency": "monthly",
                "billing_day": 1,
                "ai_optimization": true
            }
            """
            try:
                data = json.loads(body)
                customer_id = data.get('customer_id')
                policy_id = data.get('policy_id')
                
                if not customer_id or not policy_id:
                    self._set_json_headers(400)
                    self.wfile.write(json.dumps({'error': 'customer_id and policy_id required'}).encode('utf-8'))
                    return
                
                # Verify policy exists and belongs to customer
                policy = POLICIES.get(policy_id)
                if not policy:
                    self._set_json_headers(404)
                    self.wfile.write(json.dumps({'error': 'Policy not found'}).encode('utf-8'))
                    return
                
                if policy.get('customer_id') != customer_id:
                    self._set_json_headers(403)
                    self.wfile.write(json.dumps({'error': 'Policy does not belong to customer'}).encode('utf-8'))
                    return
                
                # Parse auto-pay configuration
                enabled = data.get('enabled', True)
                payment_method = data.get('payment_method', 'credit_card')
                card_last4 = data.get('card_last4', '4444')  # Default to 4444 if not provided
                card_type = data.get('card_type', 'visa')
                billing_frequency = data.get('billing_frequency', 'monthly')
                billing_day = int(data.get('billing_day', 1))
                max_amount = data.get('max_amount')
                notify_before = int(data.get('notify_before', 3))
                ai_optimization = data.get('ai_optimization', True)
                
                # Validate billing day (1-28 for safety)
                if billing_day < 1 or billing_day > 28:
                    billing_day = 1
                
                # Calculate next billing date
                now = datetime.now()
                if now.day <= billing_day:
                    next_billing = now.replace(day=billing_day)
                else:
                    # Next month
                    if now.month == 12:
                        next_billing = now.replace(year=now.year + 1, month=1, day=billing_day)
                    else:
                        next_billing = now.replace(month=now.month + 1, day=billing_day)
                
                # Build auto-pay configuration
                auto_pay_config = {
                    'enabled': enabled,
                    'payment_method': payment_method,
                    'card_last4': card_last4,
                    'card_type': card_type,
                    'billing_frequency': billing_frequency,
                    'billing_day': billing_day,
                    'max_amount': max_amount,
                    'notify_before': notify_before,
                    'ai_optimization': ai_optimization,
                    'next_billing_date': next_billing.isoformat(),
                    'configured_at': now.isoformat(),
                    'configured_by': data.get('configured_by', 'customer')
                }
                
                # Store in policy
                if 'payment_setup' not in policy:
                    policy['payment_setup'] = {}
                policy['payment_setup'].update({
                    'auto_pay': enabled,
                    'billing_frequency': billing_frequency,
                    'billing_day': billing_day,
                    'card_last4': card_last4,
                    'card_type': card_type,
                    'payment_method': payment_method,
                    'next_billing_date': next_billing.isoformat()
                })
                
                if 'billing' not in policy:
                    policy['billing'] = {}
                policy['billing'].update({
                    'auto_pay': enabled,
                    'frequency': billing_frequency,
                    'billing_day': billing_day,
                    'next_billing_date': next_billing.isoformat(),
                    'auto_pay_config': auto_pay_config
                })
                
                POLICIES[policy_id] = policy
                
                # Generate billing schedule description
                day_suffix = 'st' if billing_day == 1 else ('nd' if billing_day == 2 else ('rd' if billing_day == 3 else 'th'))
                
                if billing_frequency == 'monthly':
                    schedule_desc = f"Auto-pay on {billing_day}{day_suffix} of each month"
                elif billing_frequency == 'quarterly':
                    schedule_desc = f"Auto-pay quarterly on {billing_day}{day_suffix}"
                elif billing_frequency in ['annual', 'yearly']:
                    schedule_desc = f"Auto-pay annually on {billing_day}{day_suffix}"
                else:
                    schedule_desc = f"Auto-pay {billing_frequency}"
                
                # Format payment method display
                card_icons = {'visa': '💳', 'mastercard': '💳', 'amex': '💳', 'discover': '💳'}
                card_names = {'visa': 'Visa', 'mastercard': 'Mastercard', 'amex': 'Amex', 'discover': 'Discover'}
                
                if payment_method == 'credit_card':
                    pm_display = f"{card_names.get(card_type, 'Card')} •••• {card_last4}"
                    pm_icon = card_icons.get(card_type, '💳')
                elif payment_method == 'bank_transfer':
                    pm_display = 'Bank Account'
                    pm_icon = '🏦'
                elif payment_method == 'health_wallet':
                    pm_display = 'Health Wallet'
                    pm_icon = '💊'
                else:
                    pm_display = payment_method.replace('_', ' ').title()
                    pm_icon = '💰'
                
                # Record on transaction ledger
                config_tx = record_transaction(
                    customer_id=customer_id,
                    tx_type='auto_pay_configuration',
                    amount=0,
                    description=f"Auto-pay {'enabled' if enabled else 'disabled'} for policy {policy_id}: {schedule_desc}",
                    metadata={
                        'policy_id': policy_id,
                        'auto_pay_config': auto_pay_config,
                        'payment_method_display': pm_display,
                        'schedule': schedule_desc
                    }
                )
                
                # AI optimization note
                ai_note = ""
                if ai_optimization and enabled:
                    ai_note = " AI will optimize payment timing based on account balance patterns."
                
                response = {
                    'success': True,
                    'message': f"Auto-pay {'enabled' if enabled else 'disabled'} for policy {policy_id}",
                    'auto_pay_config': {
                        'enabled': enabled,
                        'payment_method': pm_display,
                        'payment_method_icon': pm_icon,
                        'card_type': card_type,
                        'card_last4': card_last4,
                        'schedule': schedule_desc,
                        'billing_frequency': billing_frequency,
                        'billing_day': billing_day,
                        'next_billing_date': next_billing.strftime('%Y-%m-%d'),
                        'ai_optimization': ai_optimization
                    },
                    'ai_note': ai_note.strip() if ai_note else None,
                    'nft_token_id': config_tx.get('nft_token_id'),
                    'ledger_tx_id': config_tx.get('id')
                }
                
                self._set_json_headers(200)
                self.wfile.write(json.dumps(response, default=str).encode('utf-8'))
                
            except Exception as e:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': str(e)}).encode('utf-8'))
            return
        
        # Get auto-pay settings for a policy
        if path == '/api/billing/auto-pay/settings':
            """
            Get auto-pay settings for a policy.
            
            Body params:
            - customer_id: Customer ID
            - policy_id: Policy ID
            """
            try:
                data = json.loads(body) if body else {}
                customer_id = data.get('customer_id')
                policy_id = data.get('policy_id')
                
                if not policy_id:
                    self._set_json_headers(400)
                    self.wfile.write(json.dumps({'error': 'policy_id required'}).encode('utf-8'))
                    return
                
                policy = POLICIES.get(policy_id)
                if not policy:
                    self._set_json_headers(404)
                    self.wfile.write(json.dumps({'error': 'Policy not found'}).encode('utf-8'))
                    return
                
                # Get auto-pay settings from policy
                payment_setup = policy.get('payment_setup', {})
                billing_config = policy.get('billing', {})
                auto_pay_config = billing_config.get('auto_pay_config', {})
                
                enabled = payment_setup.get('auto_pay', False) or billing_config.get('auto_pay', False)
                billing_frequency = payment_setup.get('billing_frequency') or billing_config.get('frequency', 'monthly')
                billing_day = payment_setup.get('billing_day', 1)
                card_last4 = payment_setup.get('card_last4', '4444')
                card_type = payment_setup.get('card_type', 'card')
                payment_method = payment_setup.get('payment_method', 'credit_card')
                next_billing_date = payment_setup.get('next_billing_date') or billing_config.get('next_billing_date')
                
                # Format display
                card_names = {'visa': 'Visa', 'mastercard': 'Mastercard', 'amex': 'Amex', 'discover': 'Discover', 'card': 'Card'}
                card_icons = {'visa': '💳', 'mastercard': '💳', 'amex': '💳', 'discover': '💳', 'card': '💳'}
                
                if payment_method == 'credit_card':
                    pm_display = f"{card_names.get(card_type, 'Card')} •••• {card_last4}"
                    pm_icon = card_icons.get(card_type, '💳')
                elif payment_method == 'bank_transfer':
                    pm_display = 'Bank Account'
                    pm_icon = '🏦'
                elif payment_method == 'health_wallet':
                    pm_display = 'Health Wallet'
                    pm_icon = '💊'
                else:
                    pm_display = payment_method.replace('_', ' ').title()
                    pm_icon = '💰'
                
                # Build schedule description
                day_suffix = 'st' if billing_day == 1 else ('nd' if billing_day == 2 else ('rd' if billing_day == 3 else 'th'))
                if billing_frequency == 'monthly':
                    schedule_desc = f"Auto-pay on {billing_day}{day_suffix} of each month"
                elif billing_frequency == 'quarterly':
                    schedule_desc = f"Auto-pay quarterly"
                elif billing_frequency in ['annual', 'yearly']:
                    schedule_desc = f"Auto-pay annually"
                else:
                    schedule_desc = f"Auto-pay {billing_frequency}"
                
                response = {
                    'policy_id': policy_id,
                    'customer_id': policy.get('customer_id'),
                    'auto_pay': {
                        'enabled': enabled,
                        'payment_method': pm_display,
                        'payment_method_raw': payment_method,
                        'payment_method_icon': pm_icon,
                        'card_type': card_type,
                        'card_last4': card_last4,
                        'billing_frequency': billing_frequency,
                        'billing_day': billing_day,
                        'schedule': schedule_desc,
                        'next_billing_date': next_billing_date,
                        'ai_optimization': auto_pay_config.get('ai_optimization', False),
                        'max_amount': auto_pay_config.get('max_amount'),
                        'notify_before': auto_pay_config.get('notify_before', 3)
                    }
                }
                
                self._set_json_headers(200)
                self.wfile.write(json.dumps(response, default=str).encode('utf-8'))
                
            except Exception as e:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': str(e)}).encode('utf-8'))
            return
        
        # AI Auto-Pay Execute - Process scheduled auto-pay
        if path == '/api/billing/auto-pay/execute':
            """
            Execute auto-pay for policies with scheduled payments due.
            This is called by the AI scheduler or manually triggered.
            
            Body params:
            - policy_id: Specific policy to process (optional)
            - customer_id: Specific customer to process (optional)
            - dry_run: If true, show what would be paid without executing (default false)
            """
            try:
                data = json.loads(body) if body else {}
                specific_policy = data.get('policy_id')
                specific_customer = data.get('customer_id')
                dry_run = data.get('dry_run', False)
                
                now = datetime.now()
                today = now.strftime('%Y-%m-%d')
                
                # Find all policies with auto-pay due
                policies_to_process = []
                for pol_id, policy in POLICIES.items():
                    if specific_policy and pol_id != specific_policy:
                        continue
                    if specific_customer and policy.get('customer_id') != specific_customer:
                        continue
                    
                    payment_setup = policy.get('payment_setup', {})
                    billing_config = policy.get('billing', {})
                    
                    auto_pay_enabled = payment_setup.get('auto_pay', False) or billing_config.get('auto_pay', False)
                    if not auto_pay_enabled:
                        continue
                    
                    next_billing = payment_setup.get('next_billing_date') or billing_config.get('next_billing_date')
                    if not next_billing:
                        continue
                    
                    # Check if payment is due
                    next_billing_date = next_billing[:10] if next_billing else None
                    if next_billing_date and next_billing_date <= today:
                        policies_to_process.append({
                            'policy_id': pol_id,
                            'policy': policy,
                            'customer_id': policy.get('customer_id'),
                            'next_billing_date': next_billing_date
                        })
                
                if not policies_to_process:
                    self._set_json_headers(200)
                    self.wfile.write(json.dumps({
                        'success': True,
                        'message': 'No auto-pay payments due',
                        'processed': 0,
                        'dry_run': dry_run
                    }).encode('utf-8'))
                    return
                
                # Process each policy
                payments_processed = []
                payments_failed = []
                
                for item in policies_to_process:
                    pol_id = item['policy_id']
                    policy = item['policy']
                    customer_id = item['customer_id']
                    
                    try:
                        payment_setup = policy.get('payment_setup', {})
                        billing_config = policy.get('billing', {})
                        
                        # Get payment details
                        payment_method = payment_setup.get('payment_method', 'credit_card')
                        card_last4 = payment_setup.get('card_last4', '4444')
                        card_type = payment_setup.get('card_type', 'card')
                        billing_frequency = payment_setup.get('billing_frequency') or billing_config.get('frequency', 'monthly')
                        billing_day = payment_setup.get('billing_day', 1)
                        max_amount = billing_config.get('auto_pay_config', {}).get('max_amount')
                        
                        # Calculate payment amount
                        monthly_premium = policy.get('monthly_premium', 0) or (policy.get('annual_premium', 0) / 12)
                        
                        if billing_frequency == 'quarterly':
                            amount = monthly_premium * 3 * 0.97
                        elif billing_frequency in ['annual', 'yearly']:
                            amount = monthly_premium * 12 * 0.90
                        else:
                            amount = monthly_premium
                        
                        # Check max amount limit
                        if max_amount and amount > max_amount:
                            payments_failed.append({
                                'policy_id': pol_id,
                                'customer_id': customer_id,
                                'error': f'Amount ${amount:.2f} exceeds max limit ${max_amount:.2f}'
                            })
                            continue
                        
                        if dry_run:
                            # Dry run - just report what would happen
                            payments_processed.append({
                                'policy_id': pol_id,
                                'customer_id': customer_id,
                                'amount': amount,
                                'payment_method': f"{card_type.title()} •••• {card_last4}",
                                'dry_run': True,
                                'would_process': True
                            })
                            continue
                        
                        # Execute payment - create bill and mark paid
                        bill_id = f"AUTOPAY-{now.strftime('%Y%m%d%H%M%S')}-{random.randint(1000,9999)}"
                        
                        bill = {
                            'id': bill_id,
                            'policy_id': pol_id,
                            'customer_id': customer_id,
                            'amount': amount,
                            'amount_due': amount,
                            'amount_paid': amount,
                            'status': 'paid',
                            'payment_method': payment_method,
                            'card_last4': card_last4,
                            'card_type': card_type,
                            'auto_pay': True,
                            'billing_frequency': billing_frequency,
                            'created_date': now.isoformat(),
                            'paid_date': now.isoformat(),
                            'description': f"Auto-pay premium for {pol_id}"
                        }
                        BILLING[bill_id] = bill
                        
                        # Calculate next billing date
                        if billing_frequency == 'monthly':
                            if now.month == 12:
                                next_bill = now.replace(year=now.year + 1, month=1, day=billing_day)
                            else:
                                next_bill = now.replace(month=now.month + 1, day=billing_day)
                        elif billing_frequency == 'quarterly':
                            next_month = now.month + 3
                            next_year = now.year
                            if next_month > 12:
                                next_month -= 12
                                next_year += 1
                            next_bill = now.replace(year=next_year, month=next_month, day=billing_day)
                        else:  # annual
                            next_bill = now.replace(year=now.year + 1, day=billing_day)
                        
                        # Update policy next billing date
                        policy['payment_setup']['next_billing_date'] = next_bill.isoformat()
                        if 'billing' in policy:
                            policy['billing']['next_billing_date'] = next_bill.isoformat()
                        POLICIES[pol_id] = policy
                        
                        # Record premium revenue
                        try:
                            record_premium_revenue(
                                customer_id=customer_id,
                                policy_id=pol_id,
                                amount=amount,
                                description=f"Auto-pay premium for {pol_id}"
                            )
                        except:
                            pass
                        
                        # Record on transaction ledger
                        payment_tx = record_transaction(
                            customer_id=customer_id,
                            tx_type='auto_pay_execution',
                            amount=amount,
                            description=f"Auto-pay premium ${amount:.2f} for policy {pol_id}",
                            metadata={
                                'policy_id': pol_id,
                                'bill_id': bill_id,
                                'payment_method': payment_method,
                                'card_last4': card_last4,
                                'card_type': card_type,
                                'billing_frequency': billing_frequency,
                                'next_billing_date': next_bill.isoformat()
                            }
                        )
                        
                        payments_processed.append({
                            'policy_id': pol_id,
                            'customer_id': customer_id,
                            'bill_id': bill_id,
                            'amount': amount,
                            'payment_method': f"{card_type.title()} •••• {card_last4}",
                            'next_billing_date': next_bill.strftime('%Y-%m-%d'),
                            'nft_token_id': payment_tx.get('nft_token_id')
                        })
                        
                    except Exception as pol_err:
                        payments_failed.append({
                            'policy_id': pol_id,
                            'customer_id': customer_id,
                            'error': str(pol_err)
                        })
                
                total_processed = len(payments_processed)
                total_amount = sum(p.get('amount', 0) for p in payments_processed)
                
                response = {
                    'success': True,
                    'dry_run': dry_run,
                    'processed': total_processed,
                    'total_amount': total_amount,
                    'payments': payments_processed,
                    'failed': payments_failed,
                    'message': f"{'Would process' if dry_run else 'Processed'} {total_processed} auto-pay payments totaling ${total_amount:,.2f}"
                }
                
                self._set_json_headers(200)
                self.wfile.write(json.dumps(response, default=str).encode('utf-8'))
                
            except Exception as e:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': str(e)}).encode('utf-8'))
            return
        
        # ========== CUSTOMER BILLING PROJECTIONS API (POST) ==========
        
        if path == '/api/billing/projections':
            """
            Generate billing projections for a customer (POST version).
            
            Body params:
            - customer_id: Customer ID (optional if customer_email provided)
            - customer_email: Customer email for lookup
            - policy_id: Specific policy (optional)
            - months: Projection months (default 12)
            - include_all_policies: Include all customer policies (default true)
            """
            if not billing_projection_enabled or not billing_projection_service:
                self._set_json_headers(503)
                self.wfile.write(json.dumps({
                    'error': 'Billing projection service not available'
                }).encode('utf-8'))
                return
            
            try:
                data = json.loads(body) if body else {}
            except:
                data = {}
            
            requested_customer_id = data.get('customer_id')
            customer_email = data.get('customer_email')
            policy_id = data.get('policy_id')
            projection_months = int(data.get('months', 12))
            include_all_policies = data.get('include_all_policies', True)
            
            # SECURITY: Enforce customer data isolation
            user = get_session_user(session) or {}
            role = (user.get('role') or session.get('role', '') if session else '').lower()
            session_customer_id = user.get('customer_id') or (session.get('customer_id') if session else None)
            
            if role == 'customer':
                if session_customer_id:
                    requested_customer_id = session_customer_id
                    cust = CUSTOMERS.get(session_customer_id, {})
                    if not customer_email:
                        customer_email = cust.get('email')
                else:
                    self._set_json_headers(403)
                    self.wfile.write(json.dumps({'error': 'Customer ID not found in session'}).encode('utf-8'))
                    return
            
            if not requested_customer_id and not customer_email:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': 'customer_id or customer_email required'}).encode('utf-8'))
                return
            
            try:
                projections = billing_projection_service.get_customer_billing_projection(
                    customer_id=requested_customer_id,
                    customer_email=customer_email,
                    policy_id=policy_id,
                    projection_months=projection_months,
                    include_all_policies=include_all_policies
                )
                
                if not projections:
                    self._set_json_headers(404)
                    self.wfile.write(json.dumps({
                        'error': 'No projections found for customer',
                        'customer_id': requested_customer_id,
                        'customer_email': customer_email
                    }).encode('utf-8'))
                    return
                
                projections_data = [p.to_dict() for p in projections]
                
                self._set_json_headers()
                self.wfile.write(json.dumps({
                    'success': True,
                    'projections': projections_data,
                    'total_policies': len(projections_data),
                    'projection_months': projection_months,
                    'generated_at': datetime.now().isoformat()
                }, default=str).encode('utf-8'))
            except Exception as e:
                self._set_json_headers(500)
                self.wfile.write(json.dumps({'error': str(e)}).encode('utf-8'))
            return
        
        if path == '/api/billing/projections/prepaid-discount':
            """
            Calculate prepaid premium discount.
            
            Body params:
            - customer_id: Customer ID
            - policy_id: Policy ID
            - prepaid_months: Number of months to prepay (3, 6, or 12)
            """
            if not billing_projection_enabled or not billing_projection_service:
                self._set_json_headers(503)
                self.wfile.write(json.dumps({'error': 'Billing projection service not available'}).encode('utf-8'))
                return
            
            try:
                data = json.loads(body) if body else {}
            except:
                data = {}
            
            customer_id = data.get('customer_id')
            policy_id = data.get('policy_id')
            prepaid_months = int(data.get('prepaid_months', 0))
            
            if not customer_id or not policy_id:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': 'customer_id and policy_id required'}).encode('utf-8'))
                return
            
            if prepaid_months < 1:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': 'prepaid_months must be at least 1'}).encode('utf-8'))
                return
            
            # SECURITY: Verify customer owns this policy
            policy = POLICIES.get(policy_id, {})
            if policy.get('customer_id') != customer_id:
                self._set_json_headers(403)
                self.wfile.write(json.dumps({'error': 'Policy does not belong to customer'}).encode('utf-8'))
                return
            
            try:
                result = billing_projection_service.apply_prepaid_discount(
                    customer_id=customer_id,
                    policy_id=policy_id,
                    prepaid_months=prepaid_months
                )
                
                self._set_json_headers()
                self.wfile.write(json.dumps(result, default=str).encode('utf-8'))
            except Exception as e:
                self._set_json_headers(500)
                self.wfile.write(json.dumps({'error': str(e)}).encode('utf-8'))
            return
        
        if path == '/api/billing/projections/integrity':
            """
            Validate billing data integrity (POST version).
            
            Body params:
            - customer_id: Optional customer ID for specific validation
            """
            if not billing_projection_enabled or not billing_projection_service:
                self._set_json_headers(503)
                self.wfile.write(json.dumps({'error': 'Billing projection service not available'}).encode('utf-8'))
                return
            
            try:
                data = json.loads(body) if body else {}
            except:
                data = {}
            
            requested_customer_id = data.get('customer_id')
            
            # SECURITY: Enforce role requirements
            user = get_session_user(session) or {}
            role = (user.get('role') or session.get('role', '') if session else '').lower()
            session_customer_id = user.get('customer_id') or (session.get('customer_id') if session else None)
            
            if role == 'customer':
                requested_customer_id = session_customer_id
            
            if not requested_customer_id and role not in ['admin', 'accountant']:
                self._set_json_headers(403)
                self.wfile.write(json.dumps({
                    'error': 'Admin or accountant role required for system-wide integrity check'
                }).encode('utf-8'))
                return
            
            try:
                result = billing_projection_service.validate_billing_integrity(
                    customer_id=requested_customer_id
                )
                
                self._set_json_headers()
                self.wfile.write(json.dumps(result, default=str).encode('utf-8'))
            except Exception as e:
                self._set_json_headers(500)
                self.wfile.write(json.dumps({'error': str(e)}).encode('utf-8'))
            return
        
        # ========== END BILLING PROJECTIONS API ==========
        
        # ========== BILLING CREDIT MANAGEMENT API ==========
        
        # GET Customer Credit Balance
        if path == '/api/billing/credits':
            try:
                data = json.loads(body) if body else {}
            except:
                data = {}
            
            customer_id = data.get('customer_id')
            
            # Get customer_id from session if not provided
            if not customer_id and session:
                customer_id = session.get('customer_id')
            
            if not customer_id:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': 'customer_id is required'}).encode('utf-8'))
                return
            
            if not billing_credit_enabled or not billing_credit_service:
                self._set_json_headers(503)
                self.wfile.write(json.dumps({'error': 'Billing credit service not available'}).encode('utf-8'))
                return
            
            try:
                balance = billing_credit_service.get_customer_credit_balance(customer_id)
                self._set_json_headers(200)
                self.wfile.write(json.dumps(balance, default=str).encode('utf-8'))
            except Exception as e:
                self._set_json_headers(500)
                self.wfile.write(json.dumps({'error': str(e)}).encode('utf-8'))
            return
        
        # Withdraw Credit to Bank Account
        if path == '/api/billing/credits/withdraw':
            try:
                data = json.loads(body)
            except:
                self._set_json_headers(400)
                self.wfile.write(json.dumps({'error': 'Invalid JSON body'}).encode('utf-8'))
                return
            
            customer_id = data.get('customer_id')
            amount = data.get('amount')
            withdrawal_method = data.get('method', 'bank_transfer')
            bank_details = data.get('bank_details')
            
            if not customer_id and session:
                customer_id = session.get('customer_id')
            
